/**
 * Backend contract for the ClickHouse dashboard `group_by` query param.
 *
 * Pure helpers extracted out of dashboard.vue so they can be unit-tested
 * without booting the entire page mixin chain.
 *
 * Wire format the backend expects (`dashboard_helper.py:159-233`):
 *   - URL-encoded JSON array of single-key objects, where the value is
 *     either `null` (plain group-by on that column) or one of
 *     `'day'|'week'|'month'` (DATE_TRUNC bucketing).
 *
 *   group_by=[{"supplier_name": null}]              → group by vendor
 *   group_by=[{"created_on": "month"}]              → DATE_TRUNC by month
 *   (omit param entirely)                           → flat document rows
 */

export type GroupBucket = 'day' | 'week' | 'month';

export interface GroupBySelection {
  field: string;
  bucket?: GroupBucket;
}

/**
 * Serialize a GroupBySelection (or null) into the URL query fragment
 * that gets appended to the dashboard request. Returns an empty string
 * when there is no grouping, so callers can unconditionally `+=` the
 * result without affecting non-grouped requests byte-for-byte.
 */
export function buildGroupByQueryParam(
  selection: GroupBySelection | null,
): string {
  if (!selection) return '';
  const { field, bucket } = selection;
  const payload = [{ [field]: bucket ?? null }];
  return '&group_by=' + encodeURIComponent(JSON.stringify(payload));
}
