<template>
  <q-card class="card-element">
    <q-toolbar class="bg-primary text-white">
      <q-toolbar-title>
        <span> {{ $t('document_logs') }} </span>
      </q-toolbar-title>
      <q-btn
        flat
        round
        dense
        class="primary"
        icon="close"
        @click="closePopup"
        v-close-popup
      />
    </q-toolbar>
    <DocBitsTable
      :rows="doc_logs"
      :columns="columns"
      row-key="id"
      table-id="action_details_table"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: false,
        pagination: false,
        columnReorder: false,
      }"
      no-data-label="no_record_found"
      flat-style
    >
      <template #body-cell-created_on="{ row }">
        <span class="double-field">
          <span class="font-size-16-imp">{{ row.created_by_name }}</span>
          <span>{{ formatDateAccordingToPreference(row.created_on) }}</span>
        </span>
      </template>
      <template #body-cell-action_description="{ row }">
        <span class="double-field">
          <span class="font-size-16-imp">{{ formatText(row.action_type) }}</span>
          <span>{{ row.action_description }}</span>
        </span>
      </template>
      <template #body-cell-previous_status="{ row }">
        <span class="font-size-16-imp">{{ formatText(row.previous_status) }}</span>
      </template>
      <template #body-cell-current_status="{ row }">
        <span class="font-size-16-imp">{{ formatText(row.current_status) }}</span>
      </template>
    </DocBitsTable>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import formatText from 'src/utils/string';
import { api, getAuthorizationToken } from 'pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  props: {
    docId: {
      type: String,
      required: true,
    },
  },
  mixins: [dateUtils, formatText],
  components: { DocBitsTable },
  setup() {
    return {
      doc_logs: ref([] as dynamicObj[]),
      columns: ref([] as UnifiedTableColumn[]),
    };
  },
  mounted: function () {
    this.init();
  },
  methods: {
    async init() {
      this.prepareColumns();
      await this.getDocumentLogs(this.docId);
    },

    async getDocumentLogs(docId: string) {
      try {
        let formData = new FormData();
        formData.append('action_type', '');
        formData.append('org_id', getOrgId());
        let token: string = await getAuthorizationToken();
        let response = await axios.post(
          api.get_document_log + docId,
          formData,
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (!response.data) {
          throw response;
        }
        this.doc_logs = response.data;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    closePopup() {
      this.columns = [];
      this.doc_logs = [];
    },

    prepareColumns() {
      this.columns = [
        { name: 'created_on', label: this.$t('modified_on_by'), field: 'created_on', align: 'left' },
        { name: 'action_description', label: this.$t('description'), field: 'action_description', align: 'left' },
        { name: 'previous_status', label: this.$t('previous_status'), field: 'previous_status', align: 'left' },
        { name: 'current_status', label: this.$t('current_status'), field: 'current_status', align: 'left' },
      ] as UnifiedTableColumn[];
    },
  },
});
</script>

<style lang="scss" scoped>
.card-element {
  width: 60%;
  max-width: 60%;
}

.double-field {
  display: flex;
  flex-direction: column;
}
</style>
