<!-- src/components/dashboard/GroupByChips.vue -->
<!--
  GroupByChips — chip group below/above the dashboard table that lets the
  user re-shape the document list as a backend-aggregated group view.

  Backend contract (clickhouse dashboard):
    - Frontend sends `group_by=[{<field_name>: null}]` for plain group-by,
      or `[{<field_name>: 'day'|'week'|'month'}]` for date-bucketed grouping
      (DATE_TRUNC).
    - Response.documents is then a list of bucket rows
      `{<field_name>: value, count, id}` instead of flat document rows.
    - Available group fields come back in `response.available_grouping_columns`.

  Emit shape:
    null                              → no grouping (flat view, default)
    { field: 'status' }               → group by status, no bucket
    { field: 'created_on', bucket: 'month' }  → DATE_TRUNC by month

  Date-bucketed fields render an inline day/week/month sub-toggle when
  selected; non-date fields are a single chip.
-->
<template>
  <div class="group-by-chips" data-test="group-by-chips">
    <span class="group-by-chips-label">
      {{ tf('dashboard_group_by', 'Group by') }}
    </span>

    <q-chip
      clickable
      size="sm"
      :selected="modelValue === null"
      :color="modelValue === null ? 'primary' : 'grey-3'"
      :text-color="modelValue === null ? 'white' : 'grey-8'"
      data-test="group-by-chip-none"
      @click="$emit('update:modelValue', null)"
    >
      <Icon icon="mdi:close-circle-outline" class="size-3.5 mr-1" />
      {{ tf('dashboard_group_by_none', 'None') }}
    </q-chip>

    <template v-for="opt in renderableOptions" :key="opt.field">
      <!-- Plain (non-date) chip -->
      <q-chip
        v-if="!opt.isDate"
        clickable
        size="sm"
        :selected="isActive(opt.field)"
        :color="isActive(opt.field) ? 'primary' : 'grey-3'"
        :text-color="isActive(opt.field) ? 'white' : 'grey-8'"
        :data-test="`group-by-chip-${opt.field}`"
        @click="selectField(opt.field)"
      >
        <Icon :icon="opt.icon" class="size-3.5 mr-1" />
        {{ tf(opt.labelKey, opt.fallbackLabel) }}
      </q-chip>

      <!-- Date chip with inline day/week/month sub-toggle -->
      <q-chip
        v-else
        clickable
        size="sm"
        :selected="isActive(opt.field)"
        :color="isActive(opt.field) ? 'primary' : 'grey-3'"
        :text-color="isActive(opt.field) ? 'white' : 'grey-8'"
        :data-test="`group-by-chip-${opt.field}`"
        @click="selectField(opt.field, 'month')"
      >
        <Icon :icon="opt.icon" class="size-3.5 mr-1" />
        {{ tf(opt.labelKey, opt.fallbackLabel) }}
        <span v-if="isActive(opt.field)" class="group-by-bucket-toggle" @click.stop>
          <button
            v-for="b in BUCKETS"
            :key="b"
            type="button"
            class="group-by-bucket-btn"
            :class="{ active: currentBucket === b }"
            :data-test="`group-by-bucket-${opt.field}-${b}`"
            @click="selectField(opt.field, b)"
          >
            {{ tf('dashboard_group_by_bucket_' + b, b) }}
          </button>
        </span>
      </q-chip>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent, computed, type PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { Icon } from '@iconify/vue';
import type { GroupBucket, GroupBySelection } from 'src/utils/dashboard/groupByQuery';

export type { GroupBucket, GroupBySelection };

export interface RenderableOption {
  field: string;
  labelKey: string;
  fallbackLabel: string;
  icon: string;
  isDate: boolean;
}

// Per-field UI metadata. Anything backend exposes via
// `available_grouping_columns` that's not in this map falls back to a
// generic icon + the raw field name as label — so we never hide a
// backend-supported group dimension just because we forgot to add a
// label here.
const FIELD_META: Record<string, Omit<RenderableOption, 'field'>> = {
  status: {
    labelKey: 'dashboard_group_by_status',
    fallbackLabel: 'Status',
    icon: 'mdi:flag-outline',
    isDate: false,
  },
  doc_type: {
    labelKey: 'dashboard_group_by_doc_type',
    fallbackLabel: 'Doc type',
    icon: 'mdi:file-outline',
    isDate: false,
  },
  supplier_name: {
    labelKey: 'supplier_name',
    fallbackLabel: 'Supplier Name',
    icon: 'mdi:factory',
    isDate: false,
  },
  vendor_name: {
    labelKey: 'dashboard_group_by_vendor',
    fallbackLabel: 'Vendor',
    icon: 'mdi:factory',
    isDate: false,
  },
  assigned_to: {
    labelKey: 'dashboard_group_by_assigned',
    fallbackLabel: 'Assignee',
    icon: 'mdi:account-outline',
    isDate: false,
  },
  created_on: {
    labelKey: 'dashboard_group_by_created_month',
    fallbackLabel: 'Created (Month)',
    icon: 'mdi:calendar-month-outline',
    isDate: true,
  },
  invoice_date: {
    labelKey: 'dashboard_group_by_invoice_month',
    fallbackLabel: 'Invoice (Month)',
    icon: 'mdi:calendar-month',
    isDate: true,
  },
  delivery_date: {
    labelKey: 'dashboard_group_by_delivery_month',
    fallbackLabel: 'Delivery (Month)',
    icon: 'mdi:truck-delivery-outline',
    isDate: true,
  },
};

const BUCKETS: GroupBucket[] = ['day', 'week', 'month'];

export default defineComponent({
  name: 'GroupByChips',
  components: { Icon },
  props: {
    available: {
      type: Array as PropType<string[]>,
      default: () => [],
    },
    modelValue: {
      type: Object as PropType<GroupBySelection | null>,
      default: null,
    },
  },
  emits: ['update:modelValue'],
  setup(props, { emit }) {
    const { t } = useTranslate();
    const tf = (key: string, fallback: string): string => {
      const translated = t.value(key);
      return translated !== key ? translated : fallback;
    };

    const renderableOptions = computed<RenderableOption[]>(() => {
      return props.available.map((field) => {
        const meta = FIELD_META[field];
        if (meta) return { field, ...meta };
        // Unknown backend field — render with a generic icon and raw name.
        return {
          field,
          labelKey: `dashboard_group_by_${field}`,
          fallbackLabel: field,
          icon: 'mdi:tag-outline',
          isDate: false,
        };
      });
    });

    const isActive = (field: string) => props.modelValue?.field === field;
    const currentBucket = computed<GroupBucket | undefined>(
      () => props.modelValue?.bucket,
    );

    const selectField = (field: string, bucket?: GroupBucket) => {
      const next: GroupBySelection = bucket ? { field, bucket } : { field };
      emit('update:modelValue', next);
    };

    return {
      tf,
      renderableOptions,
      isActive,
      currentBucket,
      selectField,
      BUCKETS,
    };
  },
});
</script>

<style scoped>
.group-by-chips {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 0.75rem;
}

.group-by-chips-label {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--q-color-grey-7, #6b7280);
  margin-right: 0.25rem;
}

.group-by-bucket-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.125rem;
  margin-left: 0.5rem;
  padding-left: 0.5rem;
  border-left: 1px solid rgba(255, 255, 255, 0.4);
}

.group-by-bucket-btn {
  appearance: none;
  background: transparent;
  border: 0;
  color: inherit;
  font-size: 0.6875rem;
  font-weight: 500;
  text-transform: lowercase;
  padding: 0 0.25rem;
  cursor: pointer;
  opacity: 0.65;
  transition: opacity 120ms ease;
}
.group-by-bucket-btn:hover {
  opacity: 1;
}
.group-by-bucket-btn.active {
  opacity: 1;
  text-decoration: underline;
  text-underline-offset: 2px;
}
</style>
