<template>
  <q-card class="card">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold">{{ $t('assigne_to') }}</span>
      </q-toolbar-title>

      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>

    <q-form @submit="updateAssignment">
      <q-card-section class="row">
        <div class="col-sm-12 col-md-12 col-lg-12">
          <q-select
            clearable
            use-input
            v-model="sub_org_id"
            :options="filterSubOrgsList"
            @filter="filterSubOrgslistEvent"
            @input="filertBySubOrgId"
            :label="$t('sub_organizations')"
            :loading="sub_org_list_loading"
            emit-value
            map-options
            class="card-padding"
            popup-content-class="dropdown-fit"
            outlined
            dense
          >
            <template v-slot:option="scope">
              <q-item v-bind="scope.itemProps">
                <q-item-section>
                  <q-item-label>{{ scope.opt.label }}</q-item-label>
                  <q-tooltip>{{ scope.opt.label }}</q-tooltip>
                </q-item-section>
              </q-item>
            </template>
          </q-select>
        </div>
        <div class="col-sm-12 col-md-12 col-lg-12">
          <q-select
            clearable
            use-input
            v-model="userOrGroupValue"
            :options="userOrGroupList"
            :label="$t('select_user_or_group')"
            :loading="sub_org_list_loading"
            emit-value
            map-options
            class="card-padding"
            outlined
            dense
          >
          </q-select>
        </div>
        <div class="col-sm-12 col-md-12 col-lg-12">
          <q-select
            v-if="userOrGroupValue === 'User'"
            ref="selectq"
            clearable
            v-model="user_id"
            use-input
            :id="updateUsers"
            @filter="filterUsersEvent"
            :options="filteredUserList"
            :label="$t('assigne')"
            :loading="user_list_loading"
            emit-value
            map-options
            class="card-padding"
            outlined
            dense
          />
          <q-select
            v-if="userOrGroupValue === 'Group'"
            ref="selectq"
            clearable
            v-model="group_id"
            use-input
            :id="updateGroups"
            @filter="filterGroupsEvent"
            :options="filteredGroupList"
            :label="$t('groups')"
            :loading="user_list_loading"
            emit-value
            map-options
            class="card-padding"
            outlined
            dense
          />
        </div>
      </q-card-section>
      <q-card-actions class="row" align="right">
        <q-btn flat :label="$t('cancel')" v-close-popup />
        <q-btn color="primary" unelevated :label="$t('save')" class="q-mr-sm" type="submit" />
      </q-card-actions>
    </q-form>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { useDropdownStore, useSettingStore } from 'src/store/main';
import { documentListApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    doc_ids: {
      type: Array,
      default: () => [],
    },
    doc_sub_org_id: {
      type: String,
      default: '',
    },
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    async initView() {
      this.checkIfGroupsAreActivated();
      this.prepareGroupsDropdown();
      this.prepareUsersDropdown();
      await this.getSubOrgsList();
      this.preSelectedSubOrg();
      this.filterSubOrgByid();
      this.filertBySubOrgId();
    },
    async checkIfGroupsAreActivated() {
      try {
        this.userOrGroupList = ['User', 'Group'];

        await this.startSettingsFetch();

        if (!this.user_settings['GROUP_PERMISSION_ACTIVATED']) {
          this.userOrGroupList = ['User'];
          return;
        }

        const dropdown_store = useDropdownStore();
        this.filteredGroupList = dropdown_store.groups_list;
        this.originalGroupList = dropdown_store.groups_list;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.hideLoading();
      } finally {
      }
    },
    preSelectedSubOrg() {
      const sub_org = this.subOrgList.find(
        (v: any) => v.value === this.doc_sub_org_id,
      );
      if (!sub_org) {
        return;
      }
      this.sub_org_id = sub_org.value;
    },

    filterSubOrgByid() {
      if (!this.sub_org_id) {
        return;
      }
      this.filterSubOrgsList = this.subOrgList.filter(
        (v: any) => v.value === this.sub_org_id,
      );
    },

    filertBySubOrgId() {
      if (!this.sub_org_id) {
        this.filteredUserList = this.usersList;
        return;
      }
      const sub_org_users =
        this.subOrgList.find((org: any) => org.value === this.sub_org_id)
          ?.users || [];

      if (!sub_org_users.length) {
        this.filteredUserList = this.usersList;
        return;
      }

      const sub_org_user_ids = sub_org_users.map(
        (user: dynamicObj) => user.user_id as string,
      );

      this.filteredUserList = this.usersList.filter(
        (user: dynamicObj) => sub_org_user_ids.includes(user.value) as string,
      );
    },

    filterUsersEvent(val: string, update: any, abort: any) {
      this.filertBySubOrgId();
      if (!val) {
        update(() => {
          this.filertBySubOrgId();
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredUserList = this.filteredUserList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    filterSubOrgslistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterSubOrgsList = this.subOrgList;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterSubOrgsList = this.subOrgList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    filterGroupsEvent(val: string, update: any) {
      if (!val) {
        update(() => {
          this.filteredGroupList = this.originalGroupList;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredGroupList = this.filteredGroupList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    async updateAssignment() {
      try {
        if (!this.user_id && !this.sub_org_id && !this.group_id) {
          notify.error(this.$t('no_user_sub_org_selection'));
          return;
        }
        if (this.user_id && this.group_id) {
          notify.error(this.$t('can_not_assign_to_user_and_group'));
          return;
        }

        this.showLoading();
        let data = {
          doc_ids: this.doc_ids.join(','),
          assign_to_user: this.user_id || '',
          assign_to_sub_org: this.sub_org_id || '',
          assign_to_group: this.group_id || '',
        };

        const response = await documentListApiService.assignDocuments(data);
        if (
          !response ||
          (response.hasOwnProperty('success') && response.success === false)
        ) {
          throw response;
        }
        this.hideLoading();
        notify.success(this.$t('operation_sucessfull'));
        const event = new CustomEvent('assignment_success', {});
        document.dispatchEvent(event);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.hideLoading();
      } finally {
      }
    },
  },
  setup() {
    const dropdown_store = useDropdownStore();
    const settings_store = useSettingStore();

    const filteredUserList: any = ref(dropdown_store.usersList);
    const filterSubOrgsList: any = ref(dropdown_store.subOrgList);
    const filteredGroupList: any = ref();
    const originalGroupList: any = ref();

    const { prepareUsersDropdown, getSubOrgsList, prepareGroupsDropdown } =
      dropdown_store;
    const { user_list_loading, subOrgList, sub_org_list_loading, usersList } =
      storeToRefs(dropdown_store);

    const { startSettingsFetch } = settings_store;
    const { user_settings } = storeToRefs(settings_store);

    return {
      updateUsers: ref(1),
      updateGroups: ref(1),
      getSubOrgsList,
      prepareUsersDropdown,
      prepareGroupsDropdown,
      startSettingsFetch,
      user_list_loading,
      sub_org_list_loading,
      dropdown_store,
      settings_store,
      user_settings,
      usersList,
      filteredUserList,
      subOrgList,
      filterSubOrgsList,
      filteredGroupList,
      originalGroupList,
      userOrGroupList: ref(['']),
      user_id: ref(),
      sub_org_id: ref(),
      group_id: ref(),
      userOrGroupValue: ref(),
    };
  },
});
</script>

