<!--vbase-->
<template>
  
  <div class="row justify-center q-pa-lg" data-test="dashboard-page"
    v-if="supplier_approval_status === 'pending_registration' ||
        supplier_approval_status === 'pending_supplier_input' ||
        supplier_approval_status === 'pending_approval'||
        supplier_approval_status === 'rejected'||
        supplier_approval_status === 'pending_ap_approval'">
      <SupplierApprovalStatus :status="supplier_approval_status" :supplier_as_org_id="supplier_as_org_id" :supplier_lookup_record_id="supplier_lookup_record_id" />
  </div>
  <div v-else data-test="dashboard-page">
    <!-- Visually hidden h1 for accessibility (WCAG page-has-heading-one) -->
    <h1 class="sr-only">{{ $t('dashboard') }}</h1>
    <SubHeader
      name="dashboard"
      :onSearch="false"
      :label="$t('dashboard')"
      :show_expiry_alert="true"
    />
    <div v-if="isMobile() ">
      <div class="full-width" v-if="display_data && display_data.length > 0">
        <MobileGrid :table_data="display_data" @rowClick="rowClick"/>
      </div>
      <q-markup-table flat class='full-width' v-else>
        <thead>
          <tr class='highlighted-back'>
            <th>{{$t('no_data_found')}}</th>
          </tr>
        </thead>
      </q-markup-table>

      <div class="q-pa-lg flex flex-center">
        <tr v-if="display_data.length > 0">
          <td class="text-center" colspan="10">
            <q-pagination
              v-model="paginationCount"
              color="primary"
              :max="skip"
              :max-pages="6"
              boundary-links
              @click="loadData()"
            />
          </td>
        </tr>
      </div>

    </div>
      <div
        v-else
          class="dashboard-container dashboard-text-color"
          :class="{'show-analytics' : show_analytics}"
          @drop="drop"
          @dragover="allowDrop"
          @dragleave="dragLeave"
      >
        <DashboardHeader />
        <!-- <q-separator class="seperator" /> -->
        <q-splitter
          ref="splitter"
          :horizontal="!wfLogOpen"
          :limits="[35, isDuplicatePanel ? 70 : 100]"
          :disable="!isDuplicatePanel && !wfLogOpen"
          v-model="splitterModel"
          class="dashboard-main"
          :after-class="(isDuplicatePanel) ? 'q-pa-xs' : 'q-px-sm' "
          before-class=""
          separator-class="q-ma-sm mt-n-10"
          @update:model-value="adjustTableHeightForDuplicate"
        >
          <template v-slot:before>
            <div class="full-width dashboard-list-area">
              <!-- DOCB-14285: a Touchless KPI drill-down narrows this list
                   through a query param, which is invisible next to the
                   normal filter chips. An unannounced narrowing is the
                   DRFS-733/734 lesson: the reader must be able to see WHY
                   the list is short, and undo it in one click. -->
              <q-chip
                v-if="touchlessDrilldownChip"
                removable
                square
                color="primary"
                text-color="white"
                icon="filter_alt"
                class="q-ml-sm q-mt-sm"
                data-test="touchless-drilldown-chip"
                :label="touchlessDrilldownChip"
                @remove="clearTouchlessDrilldown"
              />
              <DocTypeTabs />
              <!-- Backend-aggregated Group By chip group. Shown only when
                   the backend reports >0 groupable fields, so non-clickhouse
                   tenants don't see a dead control. -->
              <GroupByChips
                v-if="availableGroupings.length > 0"
                v-model="selectedGroupBy"
                :available="availableGroupings"
                @update:model-value="onGroupByChange"
              />
              <!-- V2 Table Implementation -->
              <DocBitsTable
                v-if="table_columns.length > 0"
                data-test="document-list"
                :rows="display_data"
                :columns="v2TableColumns"
                :column-order="v2ColumnOrder"
                row-key="id"
                :table-id="tableId"
                :features="v2TableFeatures"
                :pagination="v2PaginationState"
                :loading="show_table_loader"
                :selected-rows="selectionList"
                :table-height="isDuplicatePanel ? tableHeight : undefined"
                :pagination-settings-key="pagination_size_key"
                table-class="dashboard-height-tabs"
                no-data-label="no_document_found"
                @update:sorting="handleV2Sort"
                @update:pagination="handleV2Pagination"
                @selection-change="handleV2SelectionChange"
                @column-reorder="handleV2ColumnReorder"
                @row-click="handleV2RowClick"
                @group-prefetch="handleGroupPrefetch"
                @group-prefetch-cancel="handleGroupPrefetchCancel"
              >
                <!-- Header Actions - Bulk Actions Menu -->
                <template #header-actions>
                  <BulkActionsMenu
                    :actions="v2BulkActions"
                    :selected-count="selectionList.length"
                    :selected-rows="selectionList"
                    @action="handleV2BulkAction"
                  />
                </template>

                <!-- Status Column - Badge -->
                <template #body-cell-status="{ row }">
                  <span @click="onStatusClick($event, row)">
                    <q-badge align="middle" :class="getStatusClass(row['status'])">
                      <span style="padding: 2px;" class="dashboard-status-text">{{ getLabelTranslation(row['status']) }}</span>
                    </q-badge>
                  </span>
                  <q-tooltip
                    v-if="row['phase_timings'] && row['phase_timings'].length > 0"
                    anchor="bottom middle"
                    self="top middle"
                    :offset="[0, 6]"
                    class="phase-timeline-q-tooltip"
                  >
                    <PhaseTimelineTooltip
                      :phase-timings="row['phase_timings']"
                      :document-imported-at="row['created_on']"
                      :document-last-modified-at="row['last_modified_on']"
                      :document-status="row['status']"
                    />
                  </q-tooltip>
                  <q-tooltip v-else>
                    {{ getLabelTranslation(row['status']) }}
                  </q-tooltip>
                </template>

                <!-- Doc Type Column -->
                <template #body-cell-doc_type="{ row }">
                  {{ setDisplayDocType(row) }}
                  <q-tooltip>{{ setDisplayDocType(row) }}</q-tooltip>
                </template>

                <!-- Created On Column -->
                <template #body-cell-created_on="{ row }">
                  {{ formatDateAccordingToPreference(row['created_on']) }}
                  <q-tooltip>{{ formatDateAccordingToPreference(row['created_on']) }}</q-tooltip>
                </template>

                <!-- Last Modified On Column -->
                <template #body-cell-last_modified_on="{ row }">
                  {{ formatDateAccordingToPreference(row['last_modified_on']) }}
                  <q-tooltip>{{ formatDateAccordingToPreference(row['last_modified_on']) }}</q-tooltip>
                </template>

                <!-- Invoice Date Column -->
                <template #body-cell-invoice_date="{ row }">
                  {{ row['invoice_date'] ? formatDateAccordingToPreference(row['invoice_date'], true) : '-' }}
                  <q-tooltip v-if="row['invoice_date']">{{ formatDateAccordingToPreference(row['invoice_date'], true) }}</q-tooltip>
                </template>

                <!-- Delivery Date Column -->
                <template #body-cell-delivery_date="{ row }">
                  {{ row['delivery_date'] ? formatDateAccordingToPreference(row['delivery_date'], true) : '-' }}
                  <q-tooltip v-if="row['delivery_date']">{{ formatDateAccordingToPreference(row['delivery_date'], true) }}</q-tooltip>
                </template>

                <!-- Total Amount Column -->
                <template #body-cell-total_amount="{ row }">
                  <span class="q-ml-auto" style="padding-right: 16px;">{{ row['total_amount'] || '-' }}</span>
                  <q-tooltip v-if="row['total_amount']">{{ row['total_amount'] }}</q-tooltip>
                </template>

                <!-- Net Amount Column -->
                <template #body-cell-net_amount="{ row }">
                  <span class="q-ml-auto" style="padding-right: 16px;">{{ row['net_amount'] || '-' }}</span>
                  <q-tooltip v-if="row['net_amount']">{{ row['net_amount'] }}</q-tooltip>
                </template>

                <!-- Pages Column -->
                <template #body-cell-pages="{ row }">
                  <span class="q-ml-auto" style="display: flex; justify-content: right; padding-right: 16px;">{{ row['pages'] || '-' }}</span>
                  <q-tooltip v-if="row['pages']">{{ row['pages'] }}</q-tooltip>
                </template>

                <!-- Filename Column - Primary color text -->
                <template #body-cell-filename="{ row }">
                  <div class="align-middle full-width">
                    <span class="text-primary">{{ row['filename'] || '-' }}</span>
                    <q-tooltip v-if="row['filename']">{{ row['filename'] }}</q-tooltip>
                    <q-icon v-if="row['locked_by']" name="lock" class="filename-lock-icon q-ml-auto" size="22px">
                      <q-tooltip v-if="isLoadingUserList === false">
                        {{ showLockUser(row.locked_by) }}
                      </q-tooltip>
                      <q-tooltip v-else>
                        <q-spinner size="20px"/>
                      </q-tooltip>
                    </q-icon>
                    <div v-else class="filename-lock-placeholder q-ml-auto"></div>
                  </div>
                </template>

                <!-- Actions Column - Complex icons layout -->
                <template #body-cell-actions="{ row }">
                  <div class="action-icons-container" @click.stop>
                    <!-- Position 1: Warning Icon (only show column if any row has warnings) -->
                    <div v-if="hasAnyWarnings" class="icon-slot">
                      <template v-if="row.hasOwnProperty('warnings') && row['warnings'] && row['warnings'].length > 0">
                        <Icon icon="mdi:alert-outline" class="cursor-pointer" width="20" height="20" />
                        <q-tooltip>{{ row['warnings'].length + ' ' + $t('warnings') }}</q-tooltip>
                      </template>
                      <div v-else class="icon-placeholder"></div>
                    </div>

                    <!-- Position 2: Task Icon (only show column if any row has tasks) -->
                    <div v-if="hasAnyTasks" class="icon-slot">
                      <template v-if="row.hasOwnProperty('task_count') && row['task_count'] > 0">
                        <Icon icon="mdi:clipboard-check" class="cursor-pointer" width="20" height="20" />
                        <q-tooltip>{{ row['task_count'] + ' ' + $t('open_tasks') }}</q-tooltip>
                      </template>
                      <div v-else class="icon-placeholder"></div>
                    </div>

                    <!-- Position 3: Duplicate Document Icon (only show column if any row has duplicates) -->
                    <div v-if="hasAnyDuplicates" class="icon-slot">
                      <template v-if="(row.duplicates && row.duplicates.length > 0) || (row.related_supplier_invoices && row.related_supplier_invoices.length > 0)">
                        <Icon icon="mdi:content-duplicate" class="cursor-pointer duplicate-icon" width="20" height="20" @click="proceedToDuplicateInvoices(row)" />
                        <q-tooltip>{{ $t('show_duplicate_invoice') }}</q-tooltip>
                      </template>
                      <div v-else class="icon-placeholder"></div>
                    </div>

                    <!-- Position 4: PO Match Icon (only show column if any row has PO match) -->
                    <div v-if="hasAnyPOMatch && !isMediUser()" class="icon-slot">
                      <template v-if="row.hasOwnProperty('po_match_status') && row.hasOwnProperty('po_match_icon')">
                        <q-btn round flat size="sm" :class="row['po_match_icon'] == 'po_not_matched' ? 'cursor-not-allowed': ''" style="pointer-events: unset!important;" @click.stop="viewPurchaseOrder(row)">
                          <img :src="'/images/' + row['po_match_icon'] + '.svg'" width="20" />
                          <q-tooltip>{{ $t(row['po_match_status']) }}</q-tooltip>
                        </q-btn>
                      </template>
                      <div v-else class="icon-placeholder"></div>
                    </div>

                    <!-- Position 5: Vertex Tax Icon (only show column if any row has vertex tax) -->
                    <div v-if="hasAnyVertexTax" class="icon-slot">
                      <template v-if="row['has_vertex_tax']">
                        <img src="/images/vertex-icon.svg" class="cursor-pointer" width="20" height="20" @click="toVertexDetailsScreen(row['id'])" />
                        <q-tooltip>{{ $t('vertex_invoice_verification') }}</q-tooltip>
                      </template>
                      <div v-else class="icon-placeholder"></div>
                    </div>

                    <!-- Position 6: Actions menu button (V2 RowActionsMenu) -->
                    <div class="icon-slot">
                      <RowActionsMenu
                        :actions="v2RowActions"
                        :row="row"
                        @action="(key) => handleV2RowAction(key, row)"
                      />
                    </div>

                    <!-- Position 7: Alert icons (Restart alerts) - only show column if any row has restart_allowed -->
                    <div v-if="hasAnyRestartAllowed" class="icon-slot">
                      <template v-if="row['restart_allowed'] == true">
                        <q-icon name="priority_high" class="headerError" size="sm">
                          <q-tooltip>{{ $t('document_restart_alert') }}</q-tooltip>
                        </q-icon>
                      </template>
                      <div v-else class="icon-placeholder"></div>
                    </div>
                  </div>
                </template>
              </DocBitsTable>
            </div>
          </template>

          <template v-slot:separator >
            <q-btn v-if="isDuplicatePanel || wfLogOpen"
              :disable="!isDuplicatePanel && !wfLogOpen"
              round
              unelevated
              size="xs"
              icon="close"
              class="panel-expand-button highlighted-back z-index-1"
              @click="isDuplicatePanel ? closeSpliter() : closewfLogSplitter()"
            />
          </template>
          <template v-slot:after>
            <div v-show="isDuplicatePanel">
              <DuplicateDlalog ref="duplicateTableRef" :table_columns="table_columns" :document_ids="duplicateDocumentIds" :display_data="duplicateInvoiceList" :keyToUpdate="keyToUpdate" :tableHeight="duplicateTableHeight"/>
            </div>
            <div v-show="wfLogOpen">
              <WorkflowLogs @closeWfLog="isDuplicatePanel ? closeSpliter() : closewfLogSplitter()" :onDashboard="true" :doc_id="selectedDocIdWfLog"/>
            </div>
          </template>
        </q-splitter>
    
      <div class="flex float-right">
        <tr v-if="display_data.length > 0">
          <td class="text-center" colspan="10">

          </td>
        </tr>
      </div>
    </div>
  </div>
  <div id="drop-zone" class="hide">
    <div class="drop-zone__half top">
      <div class="drop-zone__label back-white">
        <div class="drop-zone__label-content">
          <div class="drop-zone__icon top">
            <q-icon name="sell" size="28px" />
          </div>
          <div class="drop-zone__text">
            <div class="drop-zone__title">{{ $t('classify_as') }}</div>
            <div class="drop-zone__subtitle">
              <span v-if="quickFilterMap.get('doc_type')?.name" class="drop-zone__chip">
                {{ displayDocType(quickFilterMap.get('doc_type')?.name) }}
              </span>
              <span v-else class="drop-zone__muted">{{ $t('no_doc_type_selected') }}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="drop-zone__half bottom">
      <div class="drop-zone__label back-white">
        <div class="drop-zone__label-content">
          <div class="drop-zone__icon bottom">
            <q-icon name="auto_awesome" size="28px" />
          </div>
          <div class="drop-zone__text">
            <div class="drop-zone__title">{{ $t('classify_automatically') }}</div>
            <div class="drop-zone__subtitle drop-zone__muted">{{ $t('classify_automatically') }}</div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <q-dialog v-model="deleteInvoice" persistent>
    <q-card style="min-width: 400px;">
      <q-card-section class="bg-primary text-white q-pa-md">
        <div class="row items-center">
          <q-icon name="warning" size="sm" color="white" class="q-mr-sm" />
          <div class="text-h6">{{ $t('warning_document_will_be_deleted') }}</div>
        </div>
      </q-card-section>
      <q-card-section class="q-pt-md">
        <p>{{ $t('confirm_delete_document') }}</p>
      </q-card-section>
      <q-card-actions align="right" class="q-pa-md">
        <f-btn appearance="cancel" data-cy="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          :label="$t('delete')"
          data-cy="delete-popup"
          v-close-popup
          @click="confirmDelete()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="ErrorInfos" persistent>
    <q-card class="error-details-card" style="min-width: 600px; max-width: 800px;">
      <!-- Header Section -->
      <q-card-section class="error-header">
        <div class="row items-center no-wrap">
          <q-avatar size="48px" class="error-avatar">
            <q-icon name="error_outline" size="28px" color="white" />
          </q-avatar>
          <div class="col q-ml-md">
            <div class="error-title">Processing Failed</div>
            <div class="error-filename">{{ ErrorText['row']['filename'] }}</div>
          </div>
          <q-btn 
            flat 
            round 
            icon="close" 
            size="sm" 
            v-close-popup 
            class="close-btn"
          />
        </div>
      </q-card-section>

      <!-- Failed Step Section -->
      <q-card-section class="error-content">
        <div class="failed-step-section" v-if="ErrorText.failed_step">
          <div class="section-label">
            <q-icon name="location_on" size="16px" class="q-mr-xs" />
            Failed at Step
          </div>
          <div class="failed-step-card">
            <div class="step-info">
              <div class="step-name">{{ getStepDisplayName(ErrorText.failed_step.name) }}</div>
              <div class="step-details">
                Step {{ ErrorText.failed_step.step_order }} of {{ getTotalSteps() }} • 
                {{ formatTimestamp(ErrorText.failed_step.timestamp) }}
              </div>
            </div>
            <div class="step-icon">
              <q-icon :name="getStepIcon(ErrorText.failed_step.name)" size="24px" color="red-6" />
            </div>
          </div>
        </div>

        <!-- Progress Timeline -->
        <div class="progress-timeline-section" v-if="ErrorText.previous_steps">
          <div class="section-label">
            <q-icon name="timeline" size="16px" class="q-mr-xs" />
            Processing Timeline
          </div>
          <div class="timeline-container">
            <div 
              v-for="(step, index) in ErrorText.previous_steps" 
              :key="index"
              :class="['timeline-step', getTimelineStepClass(step)]"
            >
              <div class="timeline-connector" v-if="index > 0"></div>
              <div class="timeline-icon">
                <q-icon 
                  :name="getTimelineStepIcon(step)" 
                  size="16px" 
                  :color="getTimelineStepColor(step)" 
                />
              </div>
              <div class="timeline-content">
                <div class="timeline-step-name">{{ getStepDisplayName(step.name) }}</div>
                <div class="timeline-step-details">
                  {{ step.success ? step.duration + 's' : 'Failed' }}
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- Error Details -->
        <div class="error-details-section">
          <div class="section-label">
            <q-icon name="bug_report" size="16px" class="q-mr-xs" />
            Error Details
          </div>
          <div class="error-info-card">
            <div class="error-message">{{ ErrorText.exception || ErrorText.message }}</div>
            <div class="error-metadata" v-if="ErrorText.error_context">
              <div class="error-tag">{{ ErrorText.error_context.error_category }}</div>
              <div class="error-code">{{ ErrorText.error_context.error_code }}</div>
            </div>
          </div>
        </div>

        <!-- Suggestion Section -->
        <div class="suggestion-section" v-if="ErrorText.error_context?.suggested_action">
          <div class="section-label">
            <q-icon name="lightbulb" size="16px" class="q-mr-xs" />
            Suggested Solution
          </div>
          <div class="suggestion-card">
            <q-icon name="tips_and_updates" size="20px" color="amber-7" class="q-mr-sm" />
            <span>{{ ErrorText.error_context.suggested_action }}</span>
          </div>
        </div>
      </q-card-section>

      <!-- Actions Section -->
      <q-card-actions class="error-actions">
        <q-btn 
          v-if="ErrorText.error_context?.retry_possible"
          @click="retryFromFailedStep()"
          color="primary"
          unelevated
          no-caps
          class="retry-btn"
        >
          <q-icon name="refresh" size="18px" class="q-mr-xs" />
          Retry from {{ getStepDisplayName(ErrorText.failed_step?.name || 'beginning') }}
        </q-btn>
        
        <q-btn 
          @click="viewDocFlow()"
          color="blue-grey-6"
          outline
          no-caps
          class="q-ml-sm"
        >
          <q-icon name="account_tree" size="18px" class="q-mr-xs" />
          View DocFlow
        </q-btn>
        
        <q-space />
        
        <q-btn 
          @click="copyErrorDetails()"
          flat
          color="grey-7"
          no-caps
        >
          <q-icon name="content_copy" size="16px" class="q-mr-xs" />
          Copy Details
        </q-btn>
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="QualityConfirm">
    <q-card>
      <q-card-section class="row items-center">
        <table
          cellspacing="0"
          cellpadding="0"
          style="border: none; width: 100%"
        >
          <thead>
            <tr>
              <td style="width: 5%">
                <q-avatar icon="warning" color="yellow-6" style="margin: 3%" />
              </td>
              <td>
                <div style="padding: 5%; text-align: center">
                  <b>{{ QualityText['row']['filename'] }}</b>
                </div>
              </td>
              <td style="width: 5%">
                <q-avatar icon="warning" color="yellow-6" style="margin: 3%" />
              </td>
            </tr>
          </thead>
        </table>

        <table
          cellspacing="5px"
          cellpadding="5px"
          style="border: none; width: 100%"
        >
          <thead>
            <tr>
              <td style="text-align: center">
                <span>{{ $t('low_quality') }}</span>
              </td>
            </tr>
          </thead>
        </table>
        <q-btn
          class="button-1"
          @click="restartExport(docrowID)"
          :label="$t('run_anyway')"
        />
        <q-btn
          class="button-2"
          @click="
            recordId = docrowID;
            isBulkDelete = false;
            deleteInvoice = true;
            QualityConfirm = false;
          "
          :label="$t('delete')"
        />
      </q-card-section>
    </q-card>
  </q-dialog>

  <q-dialog v-model="assigneDialog">
    <DocAssignment :doc_ids="assignment_doc_ids" :doc_sub_org_id="docSubOrgId" />
  </q-dialog>

  <q-dialog v-model="confirmMergeDialog" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('merge_doc_warning') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          :label="$t('done')"
          v-close-popup
          @click="mergeDocuments()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <q-dialog v-model="displayDocLogs">
    <ActionDetailsPopup :docId="selectedDocId"/>
  </q-dialog>

  <q-dialog v-model="exportHistoryDialog">
    <ExportHistoryPopup :docId="selectedDocId"/>
  </q-dialog>

  <q-dialog v-model="returnToValidationDialog" persistent>
    <q-card style="min-width: 400px;">
      <q-card-section class="bg-primary text-white q-pa-md">
        <div class="row items-center">
          <q-icon name="warning" size="sm" color="white" class="q-mr-sm" />
          <div class="text-h6">{{ $t('return_to_validation_warning_title') }}</div>
        </div>
      </q-card-section>

      <q-card-section class="q-pt-md">
        <p>{{ $t('return_to_validation_warning_message') }}</p>
        <p class="text-weight-medium">{{ $t('return_to_validation_confirm_question') }}</p>
      </q-card-section>

      <q-card-actions align="right" class="q-pa-md">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          :label="$t('confirm')"
          v-close-popup
          @click="confirmReturnToValidation()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <Loader />
  <q-dialog v-model="show_loading_times">
