  computed:{
    /**
     * Label for the Touchless drill-down chip, or '' when this is an ordinary
     * dashboard visit (DOCB-14285).
     *
     * Built from the SAME validated params the request is built from
     * (`extractTouchlessDrilldownParams`), so the chip cannot claim a scope
     * the query does not actually apply — a stale `touchless_bucket=FOO` is
     * dropped by both, and no chip appears for a filter that is not there.
     */
    touchlessDrilldownChip(): string {
      const params = extractTouchlessDrilldownParams(
        this.$route.query as Record<string, unknown>,
      );
      if (!params.bucket && !params.undiagnosed) return '';

      const scope = params.undiagnosed
        ? (this.$t('touchless_undiagnosed_label') as string)
        : (this.$t(
            `touchless_bucket_${params.bucket?.toLowerCase()}`,
          ) as string);

      const parts = [scope];
      if (params.windowDays !== null) {
        parts.push(
          this.$t('touchless_filter_window_days', {
            count: params.windowDays,
          }) as string,
        );
      }
      if (params.supplierKey) {
        parts.push(params.supplierKey);
      }
      return `${this.$t('touchless_filter_chip_prefix')}: ${parts.join(' \u00b7 ')}`;
    },

    isAssignToVisible(){
      let assignToVisible = false;
      if(
        (this.isAdmin && this.user_settings[this.action_assign_to] === 'only_admin') ||
