    canDeleteDocuments(): boolean {
      return Acl.canDelete(this.selectedDocuments);
    },

    /**
     * Check if user can edit selected documents (for merge, assign)
     */
    canEditDocuments(): boolean {
      return Acl.canEdit(this.selectedDocuments);
    },

    /**
     * Check if user can perform mass update on selected documents
     */
    canMassUpdate(): boolean {
      return Acl.canMassUpdate(this.selectedDocuments);
    },

    /**
     * V2 Table: Transform table_columns to UnifiedTableColumn format.
     * In grouped mode, keep the regular dashboard columns so expanding a
     * bucket shows real document rows in-place. Move the grouped field to
     * the first data column so the bucket expander appears at the beginning
     * of the row, like a tree table.
     */
    v2TableColumns(): UnifiedTableColumn[] {
      const isCurrencyLikeColumn = (field: string): boolean =>
        /(^|_)(amount|balance|price|tax|total|value)s?$/.test(field);
      const columnAlign = (field: string): 'left' | 'right' | 'center' => {
        const normalized = String(field || '').toLowerCase();
        if (normalized === 'actions') return 'center';
        if (isCurrencyLikeColumn(normalized)) return 'right';

        const meta = FIELD_CATALOG.find((item) => item.name === normalized);
        if (meta?.valueType === 'numeric') return 'right';

        if (/(^|_)(count|number|pages|quantity|qty)s?$/.test(normalized)) {
          return 'right';
        }

        return 'left';
      };

      const cols: UnifiedTableColumn[] = this.table_columns.map((col: dynamicObj) => {
        const columnName = String(col.name || '');
        const align = columnAlign(columnName);
        // DOCB-12248: format EVERY date column (API-driven via isDateValueField)
        // so columns without an explicit body-cell slot (discount_due_date,
        // due_date, invoice_due_date, assigned_on, …) still render in the
        // user's date pattern instead of the raw ISO string. QTable applies
        // `format` to compute the cell's displayed value.
        const isDate = isDateValueField(columnName);
        const fieldKey = columnName.toLowerCase();
        return {
          name: col.name,
          label: col.label || this.$t(col.name),
          // DOCB-13856: the API resolves List-of-Values labels in the user's
          // language and ships them as a sibling `<field>_label`. Prefer it for
          // display; the row keeps the canonical value, so sorting, filtering
          // and export are unaffected. Columns without a LOV have no `_label`
          // key and fall through to the raw value exactly as before.
          //
          // Date columns opt out: `field` feeds the `format` below, so a label
          // would reach formatDateAccordingToPreference instead of an ISO
          // string. A date is never LOV-backed, so nothing is lost by skipping.
          field: isDate
            ? (row: any) => row[fieldKey]
            : (row: any) =>
                lovLabel(
                  row,
                  fieldKey,
                  I18N_KEYED_ENUM_FIELDS.has(fieldKey)
                    ? (raw: string) => String(this.displayDocType(raw) ?? raw)
                    : undefined,
                ),
          sortable: col.sortable !== false,
          align,
          ...(isDate
            ? {
                format: (val: any) =>
                  this.formatDateAccordingToPreference(val),
              }
            : {}),
          classes: [
            columnName === 'status' ? 'no-truncate' : '',
            align === 'right' ? 'text-right' : '',
            'cursor-pointer',
          ].filter(Boolean).join(' ') || undefined,
        };
      });

      if (this.selectedGroupBy) {
        const groupField = this.selectedGroupBy.field;
        const groupColumnIndex = cols.findIndex((col) => col.name === groupField);
        const groupColumn =
          groupColumnIndex >= 0
            ? cols.splice(groupColumnIndex, 1)[0]
            : {
                name: groupField,
                label: this.$t(groupField) || groupField,
                field: groupField,
                sortable: false,
                align: 'left' as const,
                classes: 'cursor-pointer',
              };

        cols.unshift({ ...groupColumn, sortable: false });
      }

      // Add actions column at the end (only if not already present)
      if (!cols.some(col => col.name === 'actions')) {
        cols.push({
          name: 'actions',
          label: this.$t('actions'),
          field: 'actions',
          sortable: false,
          align: 'center' as const,
        });
      }
      return cols;
    },

    /**
     * V2 Table: Column order for persisted column reordering
     * Returns array of column names in the order they should be displayed
     */
    v2ColumnOrder(): string[] {
      // Get column names from table_columns (already sorted by order)
      const names = this.table_columns.map((col: dynamicObj) => col.name);

      if (this.selectedGroupBy) {
        const groupField = this.selectedGroupBy.field;
        const existingIndex = names.indexOf(groupField);
        if (existingIndex >= 0) {
          names.splice(existingIndex, 1);
        }
        names.unshift(groupField);
      }

      // Add actions column at the end (only if not already present)
      if (!names.includes('actions')) {
        names.push('actions');
      }
      return names;
    },

    /**
     * V2 Table: Feature configuration
     */
    v2TableFeatures() {
      return {
        sorting: true,
        filtering: false,
        selection: true,
        bulkActions: false, // We have custom bulk actions
        rowActions: false, // We use custom action column slot
        resizable: true, // Using V2 useTableResizable composable
        pagination: true,
        columnReorder: true,
        columnSettings: true, // Feature enabled (button placed separately via DashboardColumnSettings)
        stickyFirstColumn: true,
        stickyLastColumn: true,
      };
    },

    /**
     * V2 Table: Pagination state (includes sort info)
     */
    v2PaginationState() {
      return {
        sortBy: this.order_by?.field_name || null,
        descending: this.order_by?.direction === 'desc',
        page: this.paginationCount,
        rowsPerPage: Number(this.pagination_size) || 20,
        rowsNumber: this.resultsCount || 0,
      };
    },

    /**
     * Check if any row has warnings - used to show/hide warning icon column
     */
    hasAnyWarnings(): boolean {
      return this.display_data.some((row: any) =>
        row.hasOwnProperty('warnings') && row['warnings'] && row['warnings'].length > 0
      );
    },
    /**
     * Check if any row has tasks - used to show/hide task icon column
     * Also checks if tasks notification setting is enabled
     */
    hasAnyTasks(): boolean {
      if (!this.user_settings[dashboard_tasks_count_activated]) {
        return false;
      }
      return this.display_data.some((row: any) =>
        row.hasOwnProperty('task_count') && row['task_count'] > 0
      );
    },
    /**
     * Check if any row has duplicates - used to show/hide duplicate icon column
     */
    hasAnyDuplicates(): boolean {
      return this.display_data.some((row: any) =>
        (row.duplicates && row.duplicates.length > 0) ||
        (row.related_supplier_invoices && row.related_supplier_invoices.length > 0)
      );
    },
    /**
     * Check if any row has PO match status - used to show/hide PO match icon column
     */
    hasAnyPOMatch(): boolean {
      return this.display_data.some((row: any) =>
        row.hasOwnProperty('po_match_status') && row.hasOwnProperty('po_match_icon')
      );
    },
    /**
     * Check if any row has restart allowed - used to show/hide restart alert icon column
     */
    hasAnyRestartAllowed(): boolean {
      return this.display_data.some((row: any) => row['restart_allowed'] === true);
    },
    /**
     * Check if any row has vertex tax - used to show/hide vertex tax icon column
     */
    hasAnyVertexTax(): boolean {
      return this.display_data.some((row: any) => row['has_vertex_tax'] === true);
    },

    /**
     * V2 Table: Row actions configuration with show conditions
     */
    v2RowActions(): RowActionItem[] {
      return [
        {
          ...ROW_ACTION_PRESETS.validate,
          show: (row: any) => this.isDocValidatable(row),
        },
        {
          ...ROW_ACTION_PRESETS.assign,
          show: (row: any) => this.isDocReassignAble(row) && this.isAssignToVisible,
        },
        {
          ...ROW_ACTION_PRESETS.flowScreen,
        },
        {
          ...ROW_ACTION_PRESETS.download,
          show: (row: any) => this.isDocDownloadable(row),
        },
        {
          ...ROW_ACTION_PRESETS.downloadZugferd,
          show: (row: any) => this.isdownloadZugferd(row),
        },
        {
          ...ROW_ACTION_PRESETS.downloadPeppol,
          show: (row: any) => this.isdownloadPeppol(row),
        },
        {
          ...ROW_ACTION_PRESETS.downloadAnnotated,
          show: (row: any) => this.isdownloadAnnotated(row),
        },
        {
          ...ROW_ACTION_PRESETS.downloadPreview,
          show: (row: any) => this.hasPreviewFile(row),
        },
        {
          ...ROW_ACTION_PRESETS.goToExport,
          show: (row: any) => this.isExportAllowed(row['document_export_log']),
        },
        {
          ...ROW_ACTION_PRESETS.restart,
          show: (row: any) => this.isDocRestartable(row),
        },
        {
          ...ROW_ACTION_PRESETS.restartExport,
          show: (row: any) => this.isExportErrorRestart(row),
        },
        {
          ...ROW_ACTION_PRESETS.returnToValidation,
          show: (row: any) => this.isReturnToValidationVisible(row),
        },
        {
          ...ROW_ACTION_PRESETS.documentLogs,
        },
        {
          ...ROW_ACTION_PRESETS.exportHistory,
          show: (row: any) => row['status'] === CONSTANTS.export_error || row['status'] === CONSTANTS.finished,
        },
        {
          ...ROW_ACTION_PRESETS.workflowLogs,
          show: () => this.hasWorkflowsActive() && this.isAdmin,
        },
        {
          ...ROW_ACTION_PRESETS.delete,
          show: (row: any) => this.isDocDeleteable(row),
        },
      ];
    },

    /**
     * V2 Table: Bulk actions configuration with show conditions
     */
    v2BulkActions(): BulkActionItem[] {
      return [
        {
          ...BULK_ACTION_PRESETS.merge,
          show: () => this.canEditDocuments,
        },
        {
          ...BULK_ACTION_PRESETS.assign,
          show: () => this.canEditDocuments && this.isAssignToVisible,
        },
        {
          // Keep restart enabled even when some selected docs aren't
          // restartable — restartDocuments() filters them out and warns,
          // mirroring the single-row show: isDocRestartable() behaviour.
          ...BULK_ACTION_PRESETS.restart,
          show: (selectedRows: any[], selectedCount: number) =>
            this.canMassUpdate,
        },
        {
          ...BULK_ACTION_PRESETS.restartExport,
          show: (selectedRows: any[], selectedCount: number) =>
            this.canMassUpdate && !this.isMultiRestartExportDisabled,
        },
        {
          ...BULK_ACTION_PRESETS.delete,
          show: (selectedRows: any[], selectedCount: number) =>
            this.canDeleteDocuments && !this.isMultiDeleteButtonDisabled,
        },
      ];
    },
  },
  async mounted() {
    this.registerEventListeners();

    try {
      this.initailizeDragColumnsById(this.tableId);
      // await this.getProfile();
      this.getUserDetailByKey();
      //redirect to invoice dashboard if supplier is approved
      if((this.supplier_approval_status == 'approved' && isSupplierAdmin()) || (isSupplierUser() && this.supplier_approval_status == 'approved')){
        this.$router.push('/invoice/dashboard');
      }

      (<any>window).dash = this;
      this.processing = true;
      this.isAdmin = isOrganisationAdmin();

      // Guard: skip if settings already loaded by PrepareDashboard Step 3.
      // Cold-login fresh-mount used to take ~2.4s on stage; the first
      // ~400ms of that came from chaining 5 sequential awaits below.
      // startSettingsFetch sets `settingReqPromise` once; subsequent
      // getUserBasedSettings calls await that same promise internally,
      // so kicking off loadSelectedDashboardPreference + getOrderBy in
      // parallel gives a single HTTP round-trip plus concurrent
      // post-fetch JSON parse + getPaginationSize, instead of three
      // sequential await frames.  getSavedColumns still runs after
      // because it depends on `this.selected_dashboard` which step 1
      // populates.
      const settings_store = useSettingStore();
      const settingsPromise =
        objLen(settings_store.user_settings) === 0
          ? this.startSettingsFetch()
          : Promise.resolve();

      await Promise.all([
        settingsPromise,
        this.loadSelectedDashboardPreference(),
        this.getOrderBy(),
      ]);
      await this.getSavedColumns(); //not blocking due settings already fetched
      this.table_columns = await this.handleTableColumns(false);
      this.prepareStatusList();

      this.po_module_activate = true;
      this.getSavedFilters();
      this.getPaginationCount();

      // Use prefetched data from PrepareDashboard if available and fresh
      const preloadStore = useDashboardPreloadStore();
      // DOCB-14197: the preload path paints a response that was fetched
      // WITHOUT this route's query params, and never calls fetchInvoices — so
      // the deep-link block at the end of mounted() has to know that no real
      // request went out for this URL.
      let paintedFromPreload = false;
      if (preloadStore.isPreloadFresh) {
        const preloadedResponse = preloadStore.consume();
        if (preloadedResponse) {
          paintedFromPreload = true;
          this.resetPagination = false;
          this.pageSize = Number(this.pagination_size) || 20;
          this.startfrom = 0;
          this.queryParams = `?&skip=0&limit=${this.pageSize}`;
          const filterParams = await this.makeQueryParamFromFilters();
          this.queryParams += filterParams;
          this.show_table_loader = false;
          this.updateDocumentStats(preloadedResponse);
          this.updateTableData(preloadedResponse);
          this.resetPagination = true;
        } else {
          await this.loadData();
        }
      } else {
        await this.loadData();
      }
      this.clearSelectedSessionStorage();

      // disable polling
      // Updating data every 1 minute
      // this.intervalManager(true);

      this.subscribeToChannel('dashboard,dashboard_update');

      this.getDocTypeAllSettings().catch((err) => logError(err));
      this.scrollInToViewLastVisitedRow();
      this.prepareUsersDropdown();
      // this.initTableColumnResize(this.tableId);

      if (this.$route.params.force_restart &&this.$route.params.force_restart === 'force_restart') {
        this.restartExportedInvoices = true;
      }

      // Deep link: auto-open workflow logs sidebar via ?open=wf-logs&doc_id=X
      if (this.$route.query.open === 'wf-logs' && this.$route.query.doc_id) {
        this.$nextTick(() => {
          this.openWorkflowLogs(this.$route.query.doc_id as string);
        });
      }
      // Deep link: auto-open export history dialog via ?open=export-history
      if (this.$route.query.open === 'export-history') {
        this.$nextTick(() => {
          this.exportHistoryDialog = true;
        });
      }
      // Deep link: auto-open duplicate detection panel via ?open=duplicate-detection
      if (this.$route.query.open === 'duplicate-detection') {
        this.$nextTick(() => {
          this.isDuplicatePanel = true;
          this.splitterModel = 50;
          this.adjustTableHeightForDuplicate();
        });
      }
      // Deep link: preset the quick-search via
      //   ?q=<term>          — simple term; a bare document UUID becomes an
      //                        id=<uuid> chip (fast SQL path), anything else
      //                        runs as free-text search. Used by the Import
      //                        Log's doc-id buttons: /dashboard?q=<doc_id>.
      //   ?search=<raw query> — full quick-search syntax (id=…, filename=…).
      // load_saved_filter replaces the editor content and re-fires the
      // apply chain (quick-search.vue's onLoadSavedFilterEv). This block
      // sits at the END of the async mounted() — after the awaited
      // loadSelectedDashboardPreference()/loadData() — so every competing
      // dispatch (quick-search child hydration, dashboard.store loads)
      // has already fired; the deep link always lands last and wins.
      const qParam = this.$route.query.q;
      const searchParam = this.$route.query.search;
      let searchDeepLink = '';
      if (typeof qParam === 'string' && qParam.trim()) {
        const term = qParam.trim();
        const isUuid =
          /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
            term,
          );
        searchDeepLink = isUuid ? `id=${term}` : term;
      } else if (typeof searchParam === 'string' && searchParam.trim()) {
        searchDeepLink = searchParam;
      }
      if (searchDeepLink) {
        this.$nextTick(() => {
          document.dispatchEvent(
            new CustomEvent('load_saved_filter', {
              detail: { raw: searchDeepLink },
            }),
          );
          // Since DRFS-534 there is no auto-apply on parse — data reload
          // only runs on the apply_filters path. Same back-to-back pair
          // as saved-filter-badges.vue and dashboard.store.ts use.
          document.dispatchEvent(
            new CustomEvent('apply_filters', { detail: {} }),
          );
        });
      }

      // Deep link: Touchless KPI drill-down via
      //   ?touchless_bucket=<BUCKET>        — one of the five KPI tiles
      //   ?touchless_undiagnosed=true       — "N without a known cause"
      //   ?touchless_window_days=30|90      — the window the tile counted
      //
      // Unlike ?q= / ?search= these are NOT quick-search filters: they are a
      // backend-side scope, appended to every request by
      // addExtraQueryParams(), so the loadData() above already asked for the
      // scoped list and nothing more is needed here.
      //
      // The one exception is the preload path: it painted a response that was
      // prefetched before this URL existed, so it shows the WHOLE dashboard
      // under a drill-down link. Ask for the real list in that case — a KPI
      // tile that lands the user on unfiltered rows is worse than a tile that
      // does not link at all.
      if (
        paintedFromPreload &&
        hasTouchlessDrilldown(this.$route.query as Record<string, unknown>)
      ) {
        await this.loadData();
      }

      this.headerCheckbox = false;

      this.initDefaultAsignToVisible();
    } catch (err) {
      logError(err);
    } finally {
      this.processing = false;
    }
  },

  unmounted: function () {
    this.removeEventListeners();
  },

  watch: {
    // DOCB-12249 Bug #4: keep local `selectedGroupBy` in sync with the
    // store-owned `selectedGroupByState`. The store gets updated by
    // (a) onGroupByChange writethrough, and (b) setSelectedDashboard
    // restoring saved Group By from Custom Dashboard customizations.
    // Without this watcher the local v-model stays at its initial null
    // even when the loaded dashboard's customizations carry a value.
    selectedGroupByState: {
      handler(newVal) {
        const sameField =
          this.selectedGroupBy?.field === newVal?.field &&
          this.selectedGroupBy?.bucket === newVal?.bucket;
        if (sameField) return;
        this.selectedGroupBy = newVal ?? null;
      },
      immediate: true,
    },
    headerCheckbox() {
      if (this.headerCheckbox === false) {
        this.headerFabIcon = false;
        this.isMultiDeleteButtonDisabled = false;
        this.isMultiRestartExportDisabled = false;
        // this.intervalManager(true);
      } else {
        // this.intervalManager(false);
      }
    },
    processing: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.showLoading();
        } else {
          this.hideLoading();
        }
      },
    },
    websocketHasError: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.use_websocket = false;
          this.handleWebsocketDelay();
        }

      },
    },
    dashboard_data_flag: {
      handler: function (newVal, oldVal) {
        if (newVal == false) {
          return;
        }

        if (this.data_status !== 'fetching') {
          return;
        }
        this.data_status = 'received';
        this.handleWebSocketResult(this.dashboard_data);
        this.show_table_loader = false;
      },
    },
    dashboard_update_flag: {
      handler(newData) {
        this.handleWSDashboardUpdate(this.dashboard_update, this.display_data);
      },
      deep: true,
    },
    notifyUpdate:{
      handler: function (newVal, oldVal) {
        if (newVal == true && !this.notifyUpdateInExecution && this.user_settings[CONSTANTS.auto_refresh_dashboard_on_update]) {
          this.notifyUpdateInExecution = true;
          setTimeout(() => {
            this.autoUpdateRequest = true;
            this.fetchInvoices(false, false);
          }, 5000)
        }
      },
    },
  },
  methods: {
    registerEventListeners() {
      document.addEventListener('apply_filters', this.applyFilterEvent);
      document.addEventListener('reset_filters', this.resetFilters);
      document.addEventListener('reset_pages', this.resetPages);
      document.addEventListener('dashboard_refresh_data', this.refreshFilters);
      document.addEventListener('export_data_as_excel', this.handleExportDataAsExcel);
      document.addEventListener('export_data_as_csv', this.handleExportDataAsCsv);
      document.addEventListener('on_row_click', this.rowClickEvent);
      document.addEventListener(this.columns_key + '_updated', this.dashboardColumnsEvent);
      document.addEventListener('assignment_success', this.assignmentSuccess);
      document.addEventListener('apply_counter_filter', this.applyCounterFilters);
      document.addEventListener('quick_search_group_by', this.quickSearchGroupByEvent as EventListener);
      window.addEventListener('keydown', this.keyDownEvent);
      window.addEventListener('dragend', this.resetDropZone);
      window.addEventListener('drop', this.resetDropZone);
      window.addEventListener('dragleave', this.handleWindowDragLeave);
      window.addEventListener('language-changed', this.handleLanguageChanged);
      this.debounceSearchInputFunc = debounce(() => {
        this.applyFilter();
      }, 1000);
    },
    removeEventListeners() {
      document.removeEventListener('apply_filters', this.applyFilterEvent);
      document.removeEventListener('reset_filters', this.resetFilters);
      document.removeEventListener('reset_pages', this.resetPages);
      document.removeEventListener('dashboard_refresh_data', this.refreshFilters);
      document.removeEventListener('export_data_as_excel', this.handleExportDataAsExcel);
      document.removeEventListener('export_data_as_csv', this.handleExportDataAsCsv);
      document.removeEventListener('on_row_click', this.rowClickEvent);
      document.removeEventListener(this.columns_key + '_updated', this.dashboardColumnsEvent);
      document.removeEventListener('assignment_success', this.assignmentSuccess);
      document.removeEventListener('apply_counter_filter', this.applyCounterFilters);
      document.removeEventListener('quick_search_group_by', this.quickSearchGroupByEvent as EventListener);
      window.removeEventListener('keydown', this.keyDownEvent);
      window.removeEventListener('dragend', this.resetDropZone);
      window.removeEventListener('drop', this.resetDropZone);
      window.removeEventListener('dragleave', this.handleWindowDragLeave);
      window.removeEventListener('language-changed', this.handleLanguageChanged);
    },
    async handleLanguageChanged() {
      logger.language('[Dashboard] Language changed event received - refreshing table columns and clearing cache');
      const dropdown_store = useDropdownStore();
      dropdown_store.resetDocTypesSubDocTypes();
      this.table_columns = await this.handleTableColumns(false);
    },
    // ========== V2 Table Event Handlers ==========
    async handleV2Sort(payload: SortEventPayload) {
      if (payload.direction === null) {
        // Clear sort — revert to default order
        this.order_by = {} as any;
      } else {
        this.order_by = {
          field_name: payload.column,
          direction: payload.direction,
        };
      }
      this.paginationCount = 1;
      await this.saveOrderBy();

      // Fast-path: if all rows for the current filter are on this page,
      // sort client-side — no server roundtrip, no skeleton (~10ms vs 2-4s).
      const totalCount = Number(this.current_invoice_count || 0);
      const loadedCount = (this.display_data || []).length;
      const allLoaded = totalCount > 0 && loadedCount >= totalCount;

      if (allLoaded && this.order_by?.field_name) {
        if (this.applyClientSideSort(this.order_by)) return;
      }

      // Fallback: server-side sort (paginated table OR sort-clear).
      const event = new CustomEvent('apply_filters', {
        detail: {
          orderBy: this.order_by,
          reset_pagination: true,
        },
      });
      document.dispatchEvent(event);
    },

    async handleV2Pagination(payload: PaginationChangePayload) {
      this.paginationCount = payload.page;
      this.pagination_size = payload.rowsPerPage;
      this.savePaginationCount();
      // If a custom dashboard is selected, mark it as updated (shows "Save dashboard changes" button)
      // Otherwise, save to user preferences
      if (this.isDashboardSelected()) {
        this.checkForDashboardUpdates();
      } else {
        await this.setPaginationSize();
      }
      this.loadData();
    },

    handleV2RowClick(payload: RowClickPayload) {
      if (this.selectedGroupBy && (payload.row as any)?._is_group_row === true) {
        this.toggleGroupRow(payload.row as dynamicObj);
        return;
      }

      this.rowClick(payload.row, true, this.isMediUser());
    },

    handleGroupPrefetch(payload: { row: dynamicObj }) {
      if (!this.selectedGroupBy || payload.row?._is_group_row !== true) return;
      const requestKey = String(payload.row.id);
      if (
        Array.isArray(payload.row._group_children)
        || payload.row._group_loading === true
        || this.groupChildRequests[requestKey]
        || this.groupPrefetchTimers[requestKey]
      ) {
        return;
      }

      this.groupPrefetchTimers[requestKey] = window.setTimeout(() => {
        delete this.groupPrefetchTimers[requestKey];
        this.prefetchGroupRow(payload.row);
      }, 180);
    },

    handleGroupPrefetchCancel(payload: { row: dynamicObj }) {
      const requestKey = String(payload.row?.id);
      const timer = this.groupPrefetchTimers[requestKey];
      if (!timer) return;
      window.clearTimeout(timer);
      delete this.groupPrefetchTimers[requestKey];
    },

    async toggleGroupRow(row: dynamicObj) {
      const rowIndex = this.display_data.findIndex(
        (item: dynamicObj) => item.id === row.id,
      );
      if (rowIndex < 0) return;

      if (row._group_expanded === true) {
        row._group_expanded = false;
        this.display_data = this.display_data.filter(
          (item: dynamicObj) => item._group_parent_id !== row.id,
        );
        return;
      }

      if (Array.isArray(row._group_children)) {
        row._group_expanded = true;
        this.display_data.splice(rowIndex + 1, 0, ...this.buildGroupRowsForDisplay(row));
        return;
      }

      try {
        row._group_expanded = true;
        row._group_loading = true;
        const children = await this.fetchGroupChildren(row);
        row._group_children = children;
        const latestIndex = this.display_data.findIndex(
          (item: dynamicObj) => item.id === row.id,
        );
        if (row._group_expanded === true && latestIndex >= 0) {
          this.display_data.splice(latestIndex + 1, 0, ...this.buildGroupRowsForDisplay(row));
        }
        this.applyCustomFormatOnRows();
      } catch (err) {
        row._group_expanded = false;
        const apiMsg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(this.$t('ERROR_FETCHING_INVOICES'), { detail: apiMsg.detail, fullDetail: apiMsg.fullDetail });
        logError(err);
      } finally {
        row._group_loading = false;
      }
    },

    prefetchGroupRow(row: dynamicObj) {
      if (Array.isArray(row._group_children) || row._group_loading === true) return;
      row._group_loading = true;
      this.fetchGroupChildren(row).catch((err) => {
        logError(err);
      }).finally(() => {
        row._group_loading = false;
      });
    },

    async fetchGroupChildren(row: dynamicObj): Promise<dynamicObj[]> {
      const requestKey = String(row.id);
      if (this.groupChildRequests[requestKey]) {
        return this.groupChildRequests[requestKey];
      }

      this.groupChildRequests[requestKey] = documentListApiService
        .getList(this.buildGroupChildQuery(row))
        .then((response) => {
          const children = (response.documents || []).map((doc: dynamicObj) => ({
            ...doc,
            _group_child: true,
            _group_parent_id: row.id,
          }));
          row._group_children = children;
          return children;
        })
        .finally(() => {
          delete this.groupChildRequests[requestKey];
        });

      return this.groupChildRequests[requestKey];
    },

    buildGroupRowsForDisplay(row: dynamicObj): dynamicObj[] {
      const children = Array.isArray(row._group_children) ? row._group_children : [];
      const summary = this.buildGroupSummaryRow(row);
      return summary ? [...children, summary] : children;
    },

    buildGroupSummaryRow(row: dynamicObj): dynamicObj | null {
      const groupField = String(row._group_field || this.selectedGroupBy?.field || '');
      const summary: dynamicObj = {
        id: `${row.id}:summary`,
        _group_summary: true,
        _group_parent_id: row.id,
        _group_field: groupField,
        _group_value: row._group_value,
        _group_aggregate_ops: {},
      };

      this.table_columns.forEach((column: dynamicObj) => {
        const field = String(column.name || '').toLowerCase();
        if (!field || field === groupField) return;
        if (!this.isClientAggregateColumn(field)) return;
        const value = this.getGroupAggregateSourceValue(row, field);
        if (value === undefined || value === null || value === '') return;
        summary[field] = value;
        summary[`${field}_sum`] = value;
        summary._group_aggregate_ops[field] = 'sum';
      });

      return Object.keys(summary._group_aggregate_ops).length > 0 ? summary : null;
    },

    buildGroupChildQuery(row: dynamicObj): string {
      const params = new URLSearchParams(this.queryParams.replace(/^\?&?/, ''));
      params.delete('group_by');
      params.set('skip', '0');
      const defaultLimit = Number(this.pageSize || this.pagination_size || 25) || 25;
      const groupCount = Number(row._group_count) || defaultLimit;
      params.set('limit', String(Math.max(1, Math.min(groupCount, defaultLimit))));

      const field = String(row._group_field || this.selectedGroupBy?.field || '');
      const value = String(row._group_value ?? row[field] ?? '');
      params.delete('raw_where');

      const rawQuery = params.get('raw_query')?.trim();
      const predicate = this.buildGroupRawQueryPredicate(field, value);
      params.set('raw_query', rawQuery ? `${rawQuery} AND ${predicate}` : predicate);
      if (this.groupFieldRequiresFulltext(field)) {
        params.set('is_fulltext', 'true');
      }

      return '?' + params.toString();
    },

    buildGroupRawQueryPredicate(field: string, value: string): string {
      const escapedValue = value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
      return `${field}="${escapedValue}"`;
    },

    // PROB-76: resolve through the shared category resolver so per-org
    // custom doc-type fields count as fulltext. A bare FIELD_CATALOG lookup
    // returned undefined for them, so drilling into a group bucket on a
    // custom field (e.g. `m3_division`) built a raw_query predicate WITHOUT
    // `is_fulltext=true` and the backend rejected the field as unknown.
    groupFieldRequiresFulltext(field: string): boolean {
      return resolveFieldCategory(field) === 'fulltext';
    },

    /**
     * Drill down from a group-by bucket into the flat document list
     * filtered to docs in that bucket. Clears `selectedGroupBy`,
     * dispatches a `quick_search_apply_predicate` custom event so
     * `quick-search.vue` can append a chip with the bucket's value
     * (preserving the chip-editor invariant — chips are the source
     * of truth for predicates), and triggers a refetch.
     */
    drillIntoBucket(field: string, value: string) {
      this.selectedGroupBy = null;
      this.startfrom = 0;
      this.paginationCount = 1;
      this.savePaginationCount();
      this.display_data = [];
      document.dispatchEvent(
        new CustomEvent('quick_search_apply_predicate', {
          detail: { field, op: '=', value },
        }),
      );
    },

    handleV2SelectionChange(payload: any) {
      this.selectionList = payload.selectedIds;
      this.headerCheckbox = payload.totalSelected === payload.totalAvailable && payload.totalAvailable > 0;
    },

    handleV2ColumnReorder(columnNames: string[]) {
      const colsToSave = columnNames.filter(name => name !== 'actions');
      const columnsObj = colsToSave.map((name, index) => {
        const col = this.table_columns.find((c: dynamicObj) => c.name === name);
        return col ? { ...col, order: index } : null;
      }).filter(Boolean);
      this.saveSortedColumns(columnsObj, undefined, true);
    },

    /**
     * Handle V2 RowActionsMenu action clicks
     */
    handleV2RowAction(actionKey: string, row: any) {
      switch (actionKey) {
        case 'validate':
          this.rowClick(row, true, this.isMediUser());
          break;
        case 'assign':
          this.openAssignmentDlg(row);
          break;
        case 'flow-screen':
          this.toFlowScreen(row.id);
          break;
        case 'download':
          this.downloadFile(row);
          break;
        case 'download-zugferd':
          this.downloadZugferd(row);
          break;
        case 'download-peppol':
          this.downloadPeppol(row);
          break;
        case 'download-annotated':
          this.downloadAnnotated(row);
          break;
        case 'download-preview':
          this.downloadPreviewFile(row);
          break;
        case 'go-to-export':
          this.goToExport(row['document_export_log']);
          break;
        case 'restart':
          this.restartExport(row['id']);
          break;
        case 'restart-export':
          this.restartExportError(row['id']);
          break;
        case 'return-to-validation':
          this.showReturnToValidationWarning(row['id']);
          break;
        case 'document-logs':
          this.showDocLogs(row['id']);
          break;
        case 'export-history':
          this.showExportHistory(row['id']);
          break;
        case 'workflow-logs':
          this.openWorkflowLogs(row['id']);
          break;
        case 'delete':
          this.recordId = row['id'];
          this.isBulkDelete = false;
          this.deleteInvoice = true;
          break;
        default:
          console.warn(`Unknown row action: ${actionKey}`);
      }
    },

    /**
     * Handle V2 BulkActionsMenu action clicks
     */
    handleV2BulkAction(actionKey: string) {
      switch (actionKey) {
        case 'merge':
          this.confirmMerge();
          break;
        case 'assign':
          this.multipleDocAssignment();
          break;
        case 'restart':
          this.restartDocuments();
          break;
        case 'restart-export':
          this.restartDocumentsExport();
          break;
        case 'delete':
          this.isBulkDelete = true;
          this.deleteInvoice = true;
          break;
        default:
          console.warn(`Unknown bulk action: ${actionKey}`);
      }
    },
    // ========== End V2 Table Event Handlers ==========

    initDefaultAsignToVisible(){
      if(!this.user_settings[this.action_assign_to]) {
        this.user_settings[this.action_assign_to] = 'only_admin'
      }
    },
    hasWorkflowsActive() {
      if (this.user_settings[workflow_builder_setting]) {
        return true
      }
      else {
        return false
      }
    },
    openWorkflowLogs(doc_id: string) {
      // this.$router.push('/workflow_logs/' + doc_id)
      const selectedRow = document.getElementById('row_' + doc_id) as HTMLElement;
      if (this.selectedDocIdWfLog) {
        const oldSelectedRow = document.getElementById('row_' + this.selectedDocIdWfLog) as HTMLElement
        oldSelectedRow.classList.remove('light-grey-with-effect');
      }
      this.removeOldHighlight(this.highlightedRow);
      this.selectedDocIdWfLog = doc_id;
      this.wfLogOpen = true;
      this.isDuplicatePanel = false;
      this.splitterModel = 50;
      selectedRow.classList.add('light-grey-with-effect');
      return
    },
    getUserDetailByKey() {
      let organisationsFromStorage = getUserDetailFromkey('organisations');
      let FirstIndexOfOrganisations = organisationsFromStorage[0] as any;
      if(!FirstIndexOfOrganisations) {
        return;
      }
      if(['pending_ap_approval', 'pending_lt_approval'].includes(FirstIndexOfOrganisations.status)){
        this.supplier_approval_status = 'pending_approval';
      }else{
        this.supplier_approval_status = FirstIndexOfOrganisations.status
      }
      this.supplier_lookup_record_id = FirstIndexOfOrganisations.supplier_lookup_record_id ? FirstIndexOfOrganisations.supplier_lookup_record_id : 'supplier_lookup_record_id'
      this.supplier_as_org_id = FirstIndexOfOrganisations.supplier_as_org_id ? FirstIndexOfOrganisations.supplier_as_org_id : 'supplier_as_org_id'
    },
    applyFilterEvent(e: any) {
      if (e && e.detail && e.detail.reset_pagination === true) {
        this.resetPagination = true;
      }
      this.applyFilter();
    },
    emitQuerySemanticError(err: any) {
      // Bug-31 follow-up: 422 from invalid raw_query no longer fires a
      // toast (see catch blocks above), so the chip editor's inline
      // banner is the only surface left. Forward the backend's `detail`
      // string to it via DOM event — quick-search.vue listens.
      const apiMsg = ApiExceptions.getErrorMessage(err as dynamicObj);
      const message =
        (apiMsg as any)?.detail ?? String(apiMsg ?? err?.message ?? '');
      document.dispatchEvent(
        new CustomEvent('quick_search_server_validation_error', {
          detail: { message },
        }),
      );
    },
    dashboardColumnsEvent() {
      this.dashboardColumnsUpdated();
    },

    async dashboardColumnsUpdated() {
      this.table_columns = await this.fetchAndHandleTableColumns();
      await this.applySavedFilters();
      this.fetchInvoices(true);
    },

    async applySavedFilters() {
      this.pageSize = Number(this.pagination_size);
      this.queryParams = '?&skip=' + this.startfrom + '&limit=' + this.pageSize;
      this.queryParams += await this.makeQueryParamFromFilters(false);
      // this.paginationCount = this.startfrom / this.pageSize + 1;
      this.resetPagination = false;
    },

    handleActions(id: any) {
      this.display_data.forEach((row: any, index: any) => {
        if (index !== id) {
          row['fabAction'] = false;
        }
      });
      return true;
    },

    resetPages() {
      this.resetPagination = true;
    },
    /**
     * Group-by chip clicked — reset pagination and re-fetch. Backend returns
     * a different document-row shape (bucket rows) when group_by is set, so
     * we also clear `display_data` upfront to prevent the previous flat
     * rows from leaking into the new view for one frame.
     */
    onGroupByChange(_next: GroupBySelection | null) {
      this.startfrom = 0;
      this.paginationCount = 1;
      this.savePaginationCount();
      this.display_data = [];
      // DOCB-12249 Bug #4: persist Group By to the store so it survives
      // Custom Dashboard save + reload. Without this writethrough,
      // selectedGroupBy is local-only and getCustomization() saw `null`.
      this.dashboard_store.selectedGroupByState = _next;
      this.applyFilter();
    },

    /**
     * Listener for the `quick_search_group_by` custom event dispatched by
     * `pages/Dashboard/Filters/quick-search.vue` when the user types a
     * `group by <field> [bucket]` directive into the chip editor. Mirrors
     * the chip-group click path through `onGroupByChange()` so both UIs
     * (chip group + quick-search) feed the same `selectedGroupBy` state.
     */
    quickSearchGroupByEvent(e: Event) {
      const detail = (e as CustomEvent).detail as GroupBySelection | null;
      this.selectedGroupBy = detail ?? null;
      this.onGroupByChange(detail ?? null);
    },

    applyClientSideSort(
      orderBy: { field_name: string; direction: 'asc' | 'desc' } | null,
    ): boolean {
      // Sort `display_data` in-place. Returns true when sort was applied;
      // false when caller must fall back to server-side (sort-clear or no
      // sort field). Mirrors backend ORDER BY ... NULLS LAST semantics.
      if (!orderBy || !orderBy.field_name) return false;

      const field = orderBy.field_name;
      const mul = orderBy.direction === 'desc' ? -1 : 1;

      const cmp = (a: any, b: any): number => {
        const av = a?.[field];
        const bv = b?.[field];
        if (av == null && bv == null) return 0;
        if (av == null) return 1;
        if (bv == null) return -1;
        if (typeof av === 'number' && typeof bv === 'number') {
          return (av - bv) * mul;
        }
        if (typeof av === 'string' && typeof bv === 'string') {
          return av.localeCompare(bv) * mul;
        }
        return (av > bv ? 1 : av < bv ? -1 : 0) * mul;
      };

      this.display_data.sort(cmp);
      this.dashboard_store.display_data = this.display_data;
      return true;
    },

    async applyFilter() {
      this.show_table_loader = true;
      this.resetAllSelectedRows();

      if (this.resetPagination == true) {
        this.startfrom = 0;
        this.paginationCount = 1;
        this.savePaginationCount();
      }
      this.resetPagination = true;

      // Sync pageSize with current pagination_size from store
      this.pageSize = Number(this.pagination_size) || 20;
      this.queryParams = '?&skip=' + this.startfrom + '&limit=' + this.pageSize;
      const filterParams = await this.makeQueryParamFromFilters();
      this.queryParams += filterParams;
      if (!filterParams) {
        this.removeSavedFilters();
      }
      this.queryParams += buildGroupByQueryParam(this.selectedGroupBy);

      await this.fetchInvoices(true);
    },

    async refreshFilters(e:any) {
      let show_shimmer_loader = false;
      let refresh_cache = false;
      let refresh_long_cache = false;

      if (e && e.detail && e.detail.show_shimmer_loader) {
        show_shimmer_loader = true;
      }
      if (e && e.detail && e.detail.refresh_cache) {
        refresh_cache = true;
      }
      if (e && e.detail && e.detail.refresh_long_cache) {
        refresh_long_cache = true;
      }

      this.all_invoice_data = [];
      this.selectionList = [];
      this.headerCheckbox = false;
      this.closeSpliter();
      this.selectedDocIdWfLog = '';
      // Bug-2026-04-24 (Cache-Clear-Fix): AWAIT invalidate before
      // fetching. Previous version was fire-and-forget, so the
      // invalidate HTTP round-trip raced the subsequent fetchInvoices
      // — fetch usually arrived at the API before the cache-clear
      // finished, returning a stale doc_id list from the 3-min TTL
      // `SEARCH_RESULTS_CACHE`. User-visible symptom: click "Refresh
      // Table" → table still shows cached result from 30s ago.
      //
      // Grouping.vue:refreshFilters mirrors this pattern for the
      // table-rendering path; both handlers listen on the same
      // `dashboard_refresh_data` event.
      if (refresh_cache) {
        try {
          await fulltextSettingsApi.invalidateSearchCache();
        } catch (_err) {
          // Non-blocking — TTL backstop means stale-window is
          // bounded at 3 min even when invalidation fails.
        }
      }
      this.fetchInvoices(true, show_shimmer_loader, refresh_cache, refresh_long_cache);
    },

    handleExportDataAsExcel() {
      this.exportDashboardData('xlsx').catch((error) => {
        logError('Error exporting dashboard data:', error);
      });
    },

    handleExportDataAsCsv() {
      this.exportDashboardData('csv').catch((error) => {
        logError('Error exporting dashboard data:', error);
      });
    },

    async exportDashboardData (type: string) {
      try {
        // Pass the currently-selected dashboard so the export mirrors its
        // columns (custom view) instead of the org default set.
        const dashboardId = this.selected_dashboard?.id;

        // The export resolves columns from the SAVED dashboard template, so
        // unsaved on-screen column changes aren't reflected. Warn the user
        // that the last saved version is what gets exported.
        if (this.dashboard_store?.canSaveCurrentDashboard) {
          notify.warning(this.$t('export_unsaved_dashboard_warning'));
        }

        const response = await documentListApiService.exportDashboardData(this.queryParams, type, dashboardId);
          if (response.success === false) {
          throw { message: response.message };
        }

        notify.success(this.$t('export_request_added_successfully'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    /**
     * Drop the Touchless drill-down scope and reload (DOCB-14285).
     *
     * Strips the params from the URL rather than keeping a separate "ignore
     * it" flag: the URL IS the scope here — `addExtraQueryParams` reads the
     * route on every fetch — so anything else would leave a chip-less list
     * that is still narrowed, and a page reload would bring the filter back.
     */
    async clearTouchlessDrilldown() {
      const query = { ...(this.$route.query as dynamicObj) };
      delete query[TOUCHLESS_BUCKET_PARAM];
      delete query[TOUCHLESS_UNDIAGNOSED_PARAM];
      delete query[TOUCHLESS_WINDOW_PARAM];
      delete query[TOUCHLESS_SUPPLIER_PARAM];
      await this.$router.replace({ path: this.$route.path, query });
      await this.loadData();
    },

    addExtraQueryParams(refresh_long_cache: boolean) {
      //Adding refresh_long_cache param to both api and websocket request
      if (refresh_long_cache) {
          this.queryParams += '&refresh_long_cache=' + refresh_long_cache;
      }

      if (this.$route.query.debug === 'true') {
        this.queryParams += '&is_debug=true';
      }
      
      if(this.show_analytics) {
        this.queryParams += '&include_stats_summary=true';
      }

      // DOCB-14197: Touchless KPI drill-down. A tile on the Automation
      // Intelligence panel links here as
      //   /dashboard?touchless_bucket=<BUCKET>&touchless_window_days=30
      //   /dashboard?touchless_undiagnosed=true&touchless_window_days=90
      // so the list shows exactly the documents behind the number that was
      // clicked.
      //
      // Read from the route on EVERY fetch rather than applied once at mount:
      // applySavedFilters() rebuilds `queryParams` from scratch before each
      // request, so a scope applied once would survive only until the first
      // page change or re-sort — and the user would page from "the 40 process
      // exceptions" into the whole dashboard without anything on screen
      // changing. Same reason and same place as `?debug=true` above.
      //
      // The helper validates before it emits anything: an unknown bucket or a
      // window that is not 30/90 is dropped, because the backend answers 422
      // and that would surface as a generic "error fetching invoices" on a
      // dashboard that is otherwise perfectly healthy.
      this.queryParams += touchlessDrilldownQueryStringFromRoute(
        this.$route.query as Record<string, unknown>,
      );
    },

    async fetchInvoices(showLoader: boolean, show_shimmer_loader = true, refresh_cache = false, refresh_long_cache = false) {
      const fetchSource = this.use_websocket ? 'dashboard:invoices:ws' : 'dashboard:invoices:http';

      try {
        this.notifyUpdate = false;
        if (showLoader) {
          this.show_table_loader = true;
        }

        if (show_shimmer_loader) {
          this.display_data = [];
          this.selectionList = [];
          this.headerCheckbox = false;
          this.show_table_loader = true;
        }
        await this.applySavedFilters();
        this.addExtraQueryParams(refresh_long_cache);

        // One request per query: concurrent callers (watchers, filter events,
        // auto-refresh) piggy-back on the in-flight fetch instead of asking
        // the backend for the same thing again.
        const fetchKey = `${this.use_websocket ? 'ws' : 'rest'}|${this.queryParams}`;
        if (this.activeFetchKey === fetchKey && this.activeFetchPromise) {
          logger.debug(`[fetchInvoices] de-dupe in-flight ${fetchKey.slice(0, 80)}...`);
          await this.activeFetchPromise;
          this.show_table_loader = false;
          return;
        }

        this.activeFetchKey = fetchKey;
        this.activeFetchPromise = this.loadDashboardData();
        try {
          await this.activeFetchPromise;
        } finally {
          if (this.activeFetchKey === fetchKey) {
            this.activeFetchKey = null;
            this.activeFetchPromise = null;
          }
        }
      } catch (err: any) {
        // Bug-31 (2026-04-24): 422/400 = invalid raw_query. Chip-editor's
        // inline banner already communicates the cause; a toast would be
        // duplicate noise. Helper checks HTTP + WebSocket error shapes.
        if (isQueryValidationError(err)) {
          this.emitQuerySemanticError(err);
        } else {
          const apiMsg = ApiExceptions.getErrorMessage(err as dynamicObj);
          notify.error(this.$t('ERROR_FETCHING_INVOICES'), { detail: apiMsg.detail, fullDetail: apiMsg.fullDetail, source: fetchSource });
        }
        logError(err.message);
        this.show_table_loader = false;
        // DRFS-683: a failed fetch never reaches updateTableData, so the
        // previous search's window verdict would linger and decorate an
        // unrelated (or stale) count with a "+".
        this.dashboard_store.search_window_status = '';
        // DRFS-734: same reasoning for the search-path hint. A failed fetch
        // must not leave "Found in document content" attached to whatever
        // rows are still on screen — they are the PREVIOUS search's rows, and
        // the badge would then be describing results it has nothing to do
        // with.
        this.dashboard_store.search_path = '';
      }
    },

    // WebSocket first, HTTP as the fallback for the SAME query — never both
    // for a query that succeeded. `dashboardFetchGeneration` retires an
    // attempt so a late response can't paint over newer rows.
    async loadDashboardData() {
      let generation = ++this.dashboardFetchGeneration;

      if (this.use_websocket) {
        const status = await this.terminateLongRunningTask(this.getWebSocketDashboard(generation), 10000);
        if (this.dashboardFetchGeneration !== generation) {
          return;
        }
        if (status !== 'timeout' && status !== 'failed') {
          this.show_table_loader = false;
          return;
        }
        // WebSocket gave up. Retire this attempt so a late WS response cannot
        // overwrite what HTTP is about to render, then retry over HTTP with
        // this fetch's queryParams — same skip, so the page stays put.
        this.use_websocket = false;
        this.data_status = 'received';
        generation = ++this.dashboardFetchGeneration;
      }

      const response = await this.fetchDashboardList();
      if (this.dashboardFetchGeneration !== generation) {
        return;
      }

      this.updateDocumentStats(response);
      this.updateTableData(response);
      clearErrorSource('dashboard:invoices:ws');
      clearErrorSource('dashboard:invoices:http');
      this.show_table_loader = false;
      setTimeout(this.turnOnWebSocket, 5000);
    },

    async fetchDashboardList() {
      if (!this.selectedGroupBy) {
        return documentListApiService.getList(this.queryParams);
      }

      try {
        const response = await documentListApiService.getListFromWarehouse(this.queryParams);
        if (response?.success === false) {
          throw response;
        }
        return response;
      } catch (err) {
        logger.warn('[dashboard] Falling back to client-side grouped REST data', err);
        const response = await documentListApiService.getList(
          this.buildUngroupedDashboardQuery(this.queryParams),
        );
        return {
          ...response,
          documents: this.prepareClientGroupRows(response?.documents || []),
          __client_grouped: true,
        };
      }
    },

    buildUngroupedDashboardQuery(query: string): string {
      const params = new URLSearchParams(query.replace(/^\?&?/, ''));
      params.delete('group_by');
      params.set('skip', '0');
      const limit = Number(this.pageSize || this.pagination_size || 25) || 25;
      params.set('limit', String(limit));
      return '?' + params.toString();
    },

    prepareClientGroupRows(rows: dynamicObj[]): dynamicObj[] {
      const groupField = this.selectedGroupBy?.field;
      if (!groupField) return rows;

      const groups = new Map<string, { value: unknown; label: unknown; count: number; sums: Record<string, number> }>();
      rows.forEach((row: dynamicObj) => {
        const groupValue = row[groupField] ?? row.label ?? row.value ?? row.key ?? '';
        // DOCB-13856: group on the CANONICAL value (never split a group by
        // language) but carry the API's translated label along for the header.
        const groupLabel = lovLabel(row, groupField);
        const key = this.getNormalizedGroupKey(groupValue);
        const current = groups.get(key);
        const group = current ?? { value: groupValue, label: groupLabel, count: 0, sums: {} as Record<string, number> };
        group.count += 1;

        this.table_columns.forEach((column: dynamicObj) => {
          const field = String(column.name || '').toLowerCase();
          if (!field || field === groupField) return;
          if (!this.isClientAggregateColumn(field)) return;
          const numericValue = this.parseAggregateNumber(this.getGroupAggregateSourceValue(row, field));
          if (numericValue === null) return;
          group.sums[field] = (group.sums[field] || 0) + numericValue;
        });

        if (!current) {
          groups.set(key, group);
        }
      });

      return Array.from(groups.values()).map((group, index) => {
        const row: dynamicObj = {
          [groupField]: group.value,
          id: `client-group:${groupField}:${String(group.value ?? '')}:${index}`,
          _is_group_row: true,
          _group_field: groupField,
          _group_value: group.value,
          _group_label: this.formatGroupValue(groupField, group.label ?? group.value),
          _group_count: group.count,
          _group_expanded: false,
        };

        Object.entries(group.sums).forEach(([field, value]) => {
          row[field] = value;
          row[`${field}_sum`] = value;
        });

        return row;
      });
    },

    isClientAggregateColumn(field: string): boolean {
      if (field === 'pages') return false;

      return /(^|_)(amount|balance|price|quantity|qty|sum|tax|total|value)s?$/.test(field);
    },

    parseAggregateNumber(value: unknown): number | null {
      if (typeof value === 'number') {
        return Number.isFinite(value) ? value : null;
      }
      if (typeof value !== 'string') return null;

      const normalized = value.trim().replace(/\s/g, '');
      if (!normalized || normalized === '-') return null;

      const numberValue = Number(normalized.replace(/,/g, ''));
      return Number.isFinite(numberValue) ? numberValue : null;
    },

    handleWebsocketDelay () {
      // websocket is still fetching data and we are not getting any response
      if (this.data_status === 'received') {
        return;
      }
      this.disableWebsocketAndReconnect();
      // A fetch already in flight runs its own HTTP retry with the correct
      // skip — a detached one here would race it and land page-1 data.
      if (this.activeFetchPromise) {
        return;
      }
      this.fetchInvoices(false, false);
      this.show_table_loader = false;
    },

    disableWebsocketAndReconnect () {
      this.dashboard_data_flag = false;
      this.use_websocket = false;

      // Actively reconnect WebSocket in background via the store's
      // exponential backoff mechanism (1s → 2s → 4s → ... → 60s, max 10 retries)
      const websocket_store = useWebSocketStore();
      websocket_store.scheduleReconnect();

      // Re-enable WebSocket usage once the store reconnects
      const unwatch = watch(
        () => websocket_store.isConnected,
        (connected) => {
          if (connected) {
            this.use_websocket = true;
            unwatch();
          }
        },
      );

      // Safety: stop watching after 5 minutes to avoid memory leaks
      setTimeout(() => unwatch(), 300000);
    },

    turnOnWebSocket () {
      if (this.websocketHasError) {
        // Reset error state and attempt reconnection via store
        const websocket_store = useWebSocketStore();
        websocket_store.backoff.reset();
        websocket_store.hasError = false;
        websocket_store.scheduleReconnect();
        return;
      }

      this.use_websocket = true;
    },

    terminateLongRunningTask(promise: any, ms: number): Promise<any> {
        return new Promise<any>((resolve, reject) => {
            const timer = setTimeout(() => {
                logger.debug('WebSocket operation timed out, falling back to HTTP');
                this.disableWebsocketAndReconnect();
                // Resolve instead of reject - timeout is an expected fallback
                // scenario. The caller owns the HTTP retry so it keeps this
                // fetch's pagination.
                resolve('timeout');
            }, ms);

            promise.then((result: any) => {
                    clearTimeout(timer);
                    resolve(result);
                })
                .catch((err: any) => {
                    clearTimeout(timer);
                    this.disableWebsocketAndReconnect();
                    reject(err);
                });
        });
    },

    updateTableData(response: dynamicObj) {

      // DRFS-683: the backend delegates search to OpenSearch and gets back a
      // capped window of matches. When that window is truncated (or its
      // completeness is unknown), the count below only describes the window,
      // not the full match set — the badge renders "1.234+" instead of a
      // number the user would read as exact. Counts stay numeric so
      // pagination math is unaffected.
      // Assigned FIRST, before the early returns below (row selection,
      // sort self-heal): a later response that is complete must clear a
      // previous "+", even on a path that skips the table update.
      this.dashboard_store.search_window_status =
        ((response as dynamicObj)?.search_meta?.window_status as string) || '';

      // DRFS-734: which tier answered this search. Rides the SAME
      // `search_meta` channel as the window status above and is assigned in
      // the same place, before the early returns, so a later plain-fields
      // response always clears a previous content-fallback hint — otherwise
      // the badge would stick to a result set that no longer has anything to
      // do with document content.
      this.dashboard_store.search_path =
        ((response as dynamicObj)?.search_meta?.search_path as string) || '';

      // DRFS-683 follow-up: the count is assigned here, above the early returns,
      // for exactly the same reason as search_window_status. It used to be
      // written at the END of this method, so any response that took the
      // row-selection or sort-self-heal exit left the PREVIOUS query's count on
      // screen — a zero-match search rendered an empty table still labelled
      // "All documents (1124)". Only the first search after a fresh load was
      // affected, because re-running it no longer trips the self-heal guard
      // (sortHealAttempted is already set), so the count reached this code.
      // DRFS-752: test the TYPE, never the truthiness. `0` is a legitimate
      // results-count and it is falsy, so the old `&& response.overview[...]`
      // guard sent a zero-match search down the else branch and left
      // `resultsCount` on the PREVIOUS query's value: an empty table under
      // "1-20 of 1355", with clickable pages that fetch nothing. Reset the
      // paginator on 0 like on any other number.
      //
      // DRFS-752 follow-up: the else branch has to reset the PAGER too, not
      // only the header badge. It zeroed `current_invoice_count` and left
      // `resultsCount`/`skip` on the previous query's values, and those two are
      // what the footer renders (`rowsNumber: this.resultsCount || 0` above,
      // `:max="skip"` on the q-pagination) — so an unusable response showed
      // "none" in the header over "58 Total, 1/3" in the pager. It is reachable:
      // `dashboard_populator.py` answers its generic exception handler with
      // HTTP 200 and `{"success": false}`, and `DocumentListSDKWrapper.getList`
      // returns that body without throwing. Every number on the page describes
      // the same response, or none of them do.
      const resultsCountValue = response?.overview?.['results-count'];
      if (typeof resultsCountValue === 'number') {
        this.resultsCount = resultsCountValue;
        this.current_invoice_count = this.resultsCount;
        let temp = this.resultsCount / this.pageSize;
        this.skip = Math.ceil(temp);
      } else {
        this.resultsCount = 0;
        this.skip = 0;
        this.current_invoice_count = 0;
      }

      // Pick up the backend's groupable-columns hint on every response —
      // safe to read whether or not we asked for grouping. The backend
      // always sets this field (`dashboard_helper.py:792, 854`).
      if (Array.isArray(response.available_grouping_columns)) {
        this.availableGroupings = response.available_grouping_columns;
      }

      if (this.selectionList.length > 0 || !response.documents) {
        // dont refresh if user is in the middle of something
        this.show_table_loader = false;
        return;
      }

      // Self-heal: if the response counts documents for THIS query but the
      // page came back empty AND a sort is active, the sort field probably
      // isn't indexed yet (e.g. OpenSearch populated later than Postgres).
      // Clear the sort once and refetch so the user sees something rather
      // than an empty table. `sortHealAttempted` guards against loops.
      //
      // DRFS-751: the trigger reads `results-count`, not `all-invoices`.
      // `all-invoices` used to be an org-wide total that ignored every
      // active filter, so a search legitimately matching nothing looked
      // exactly like a broken sort — the page silently dropped the user's
      // chosen sort order and refetched. `results-count` describes the
      // filtered population (and since DRFS-751 so does `all-invoices`), so
      // an honest zero no longer fires a reset; a genuine count/list
      // disagreement — the only thing this heal is for — still does.
      const matchedForThisQuery = Number(
        response?.overview?.['results-count'] ?? 0,
      );
      if (
        response.documents.length === 0
        && matchedForThisQuery > 0
        && !this.sortHealAttempted
        && this.dashboard_store?.order_by?.field_name
      ) {
        this.sortHealAttempted = true;
        this.dashboard_store.order_by = {};
        this.order_by = {};
        this.fetchInvoices(true, false);
        return;
      }
      // Reset guard once a non-empty page lands.
      if (response.documents.length > 0) {
        this.sortHealAttempted = false;
      }

      // The page the user is on no longer exists (filter narrowed the result
      // set, documents deleted): go back to page 1. Checked HERE, against a
      // response that actually arrived — checking `display_data` in
      // fetchInvoices also matched a shimmer-cleared table whose response was
      // still in flight, which is what threw the user off the last page.
      if (response.documents.length === 0 && this.paginationCount !== 1) {
        this.paginationCount = 1;
        LocalStorage.removeItem(getUserBasedKey(dashboard_pagination));
        // Next tick, so the caller of this response is done turning the table
        // loader off before the page-1 reload turns it back on.
        this.$nextTick(() => this.loadData());
        return;
      }

      let resetColumResizer = false;

      const incomingDocuments = this.selectedGroupBy && !response.__client_grouped
        ? this.prepareGroupRows(response.documents)
        : response.documents;

      if(incomingDocuments.length != this.display_data.length) {
        resetColumResizer = true;
      }

      // will work for websocket auto update case
      if(this.autoUpdateRequest && this.notifyUpdateInExecution) {
        this.autoUpdateRequest = false;
        this.notifyUpdateInExecution = false;
        this.syncArrays(incomingDocuments);
      } else {
        // will work for normal refresh case
        for (let index = 0; index < incomingDocuments.length; index++) {
          const newDoc = incomingDocuments[index];
          const currentDoc = this.display_data[index];
          if (!this.isRowEqual(currentDoc, newDoc)) {
            this.display_data = incomingDocuments;
            break;
          }
        }
      }

      this.applyCustomFormatOnRows();

      // Sync display_data to Pinia store for Cmd+K document picker
      this.dashboard_store.display_data = this.display_data;

      this.$nextTick(() => {
        this.scrollInToViewLastVisitedRow();
      });

      this.show_table_loader = false;
    },

    prepareGroupRows(rows: dynamicObj[]) {
      const groupField = this.selectedGroupBy?.field;
      if (!groupField) return rows;

      const groups = new Map<string, { value: unknown; label: unknown; count: number; sums: Record<string, number> }>();
      rows.forEach((row: dynamicObj) => {
        const groupValue = row[groupField] ?? row.label ?? row.value ?? row.key;
        // DOCB-13856: see prepareClientGroupRows — group on the canonical
        // value, display the API's translated label when one is present.
        const groupLabel = lovLabel(row, groupField);
        const key = this.getNormalizedGroupKey(groupValue);
        const current = groups.get(key);
        const group = current ?? { value: groupValue, label: groupLabel, count: 0, sums: {} as Record<string, number> };
        group.count += this.getGroupRowCount(row);

        this.table_columns.forEach((column: dynamicObj) => {
          const field = String(column.name || '').toLowerCase();
          if (!field || field === groupField) return;
          if (!this.isClientAggregateColumn(field)) return;
          const numericValue = this.parseAggregateNumber(this.getGroupAggregateSourceValue(row, field));
          if (numericValue === null) return;
          group.sums[field] = (group.sums[field] || 0) + numericValue;
        });

        if (!current) {
          groups.set(key, group);
        }
      });

      return Array.from(groups.values()).map((group, index) => {
        const row: dynamicObj = {
          [groupField]: group.value,
          id: `group:${groupField}:${String(group.value ?? '')}:${index}`,
          _is_group_row: true,
          _group_field: groupField,
          _group_value: group.value,
          _group_label: this.formatGroupValue(groupField, group.label ?? group.value),
          _group_count: group.count,
          _group_expanded: false,
        };

        Object.entries(group.sums).forEach(([field, value]) => {
          row[field] = value;
          row[`${field}_sum`] = value;
        });

        return row;
      });
    },

    getNormalizedGroupKey(value: unknown): string {
      return String(value ?? '').trim().toLocaleLowerCase();
    },

    getGroupAggregateSourceValue(row: dynamicObj, field: string): unknown {
      const direct = row[field];
      if (direct !== undefined && direct !== null && direct !== '') return direct;

      const keys = [
        `${field}_sum`,
        `sum_${field}`,
        `${field}_total`,
        `total_${field}`,
        `${field}_count`,
        `count_${field}`,
      ];
      for (const key of keys) {
        const value = row[key];
        if (value !== undefined && value !== null && value !== '') return value;
      }

      const nested = row.aggregates?.[field] ?? row.aggregate?.[field];
      if (nested && typeof nested === 'object') {
        for (const op of ['sum', 'total', 'count']) {
          const value = nested[op];
          if (value !== undefined && value !== null && value !== '') return value;
        }
      }

      return undefined;
    },

    getGroupRowCount(row: dynamicObj): number {
      const count = [
        row.count,
        row.documents,
        row.document_count,
        row.documents_count,
        row.doc_count,
        row.docs_count,
        row.total_count,
        row.total,
        row._count,
        row.Documents,
      ]
        .map((value) => Number(value))
        .find((value) => Number.isFinite(value) && value > 0);

      return count ?? 1;
    },

    formatGroupValue(field: string, value: unknown): string {
      if (field === 'status') {
        return this.getLabelTranslation(String(value));
      }
      if (field === 'doc_type') {
        return String(this.displayDocType(value));
      }
      if (this.date_fields?.includes(field)) {
        return this.formatDateAccordingToPreference(value, true);
      }
      return String(value ?? '-');
    },
    
    syncArrays(newDocuments: any[]) {
      const newDocumentsMap = new Map(newDocuments.map(item => [item.id, item]));
       
      const displayDataMap = new Set(this.display_data.map(item => item.id));
      // Two-way check
      const allIdsMatch = this.display_data.every(item => newDocumentsMap.has(item.id)) && newDocuments.every(item => displayDataMap.has(item.id));

      if (allIdsMatch) {
        this.display_data.forEach(item => {
          Object.assign(item, newDocumentsMap.get(item.id));
        });
      } else {
        this.display_data = newDocuments;
      }
    },

