    allowDrop(event: any) {
      // if a column or doc type tab is being dragged, don't show drop zone
      if (this.storeIsColumnDragging || this.storeIsTabDragging) return;
      
      event.preventDefault();
      this.dragDepth++; // Increment depth (stabilize overlay)
      const element = document.getElementById('drop-zone')
      element?.classList.add('drop-zone')
      
      const dropY = event.clientY
      const screenHeight = window.innerHeight
      if (dropY < screenHeight / 2) {
        element?.classList.add('active-top')
        element?.classList.remove('active-bottom')
      } else {
        element?.classList.add('active-bottom')
        element?.classList.remove('active-top')
      }
    },

    drop(event: any) {
      // if a column or doc type tab is being dragged, don't accept file drop
      if (this.storeIsColumnDragging || this.storeIsTabDragging) return;
      
      event.preventDefault();
      const element = document.getElementById('drop-zone')
      element?.classList.remove('drop-zone', 'active-top', 'active-bottom')

      // Reset depth counter
      this.resetDropZone();

      if(!event.dataTransfer.files || event.dataTransfer.files.length == 0) return;
      
      const dropY = event.clientY
      const screenHeight = window.innerHeight
      if (dropY < screenHeight / 2) {
        if (this.quickFilterMap.get('doc_type') && this.quickFilterMap.get('doc_type').value != 'all') {
          this.upload_classify_doctype = this.quickFilterMap.get('doc_type').value;
        }
      } else {
        this.upload_classify_doctype = ''
      }
      this.uploadFiles(event.dataTransfer.files);
    },

    dragLeave(event: any) {
      // if a column or doc type tab is being dragged, ignore
      if (this.storeIsColumnDragging || this.storeIsTabDragging) return;
      
      event.preventDefault();
      this.dragDepth--;
      // Only hide when we've fully left all dragged zones
      if (this.dragDepth <= 0) {
        this.resetDropZone();
      }
    },

    uploadFiles(files: any) {
