    checkRowExistance(id : any,checkAble: boolean) {
      const rowIndex = this.display_data.findIndex((row: dynamicObj) => row.id === id);
      if(rowIndex !== -1){
        const row = this.display_data[rowIndex];
        if(checkAble){
          // this.is_any_checked = true;
          this.selectionList.push(row.id);
          this.noOfSelections = this.noOfSelections +1;
          if (this.isMultiDeleteButtonDisabled === false) {
            this.isMultiDeleteButtonDisabled = !this.isDocDeleteable(row);
          }
          if (this.isMultiRestartExportDisabled === false) {
            this.isMultiRestartExportDisabled = !this.isDocExportRestartable(row);
          }
        }else{
          this.isMultiDeleteButtonDisabled = false;
          this.noOfSelections = this.noOfSelections -1 ;
          const indexToRemove = this.selectionList.indexOf(id);
          if (indexToRemove !== -1) {
            this.selectionList.splice(indexToRemove, 1);
          }
          this.selectionList.forEach((row_id: string) => {
            const row = this.display_data.find((row: dynamicObj) => row.id === row_id)
            if (!this.isDocDeleteable(row)) {
              this.isMultiDeleteButtonDisabled = true;
            }
          });
        }
      }

      if (this.noOfSelections === 0) {
        this.headerCheckbox = false;
        this.isMultiDeleteButtonDisabled = false;
        this.isMultiRestartExportDisabled = false;
      } else if (this.display_data.length === this.noOfSelections) {
        this.headerCheckbox = true;
      } else {
        this.headerCheckbox = false;
      }
    },

    applyOptimisticRestartUpdate(docIds: string[]) {
      // Mutate the affected rows in place — no full-table refetch.
      // The WebSocket subscription will push subsequent status/phase
      // updates as the new pipeline iteration runs.
      if (!docIds || docIds.length === 0) return;
      const now = new Date().toISOString();
      const idSet = new Set(docIds);
      for (const row of this.display_data as any[]) {
        if (row && idSet.has(row.id)) {
          row['status'] = 'restarted';
          row['phase_timings'] = [];
          row['last_modified_on'] = now;
        }
      }
      this.dashboard_store.display_data = this.display_data;
    },

    async restartDocuments() {
      // Mirror the single-row restart rule (show: isDocRestartable): only
      // process docs the user is allowed to restart, and warn about the rest
      // instead of blocking the whole action.
      const selectedRows = this.selectedDocuments;
      const restartableRows = selectedRows.filter((row: dynamicObj) => this.isDocRestartable(row));
      const skippedCount = selectedRows.length - restartableRows.length;
      const restartedIds = restartableRows.map((row: dynamicObj) => row.id);

      if (restartedIds.length === 0) {
        notify.error(this.$t('RESTART_NO_PERMISSION', { count: skippedCount }));
        return;
      }
      try {
        this.processing = true;
        const response = await documentListApiService.restartDocuments(
          restartedIds.join(','),
          this.restartExportedInvoices
        );
        if (response.success === false) {
          throw response;
        }
        this.headerCheckbox = false;
        this.resetAllSelectedRows();
        this.applyOptimisticRestartUpdate(restartedIds);
        if (skippedCount > 0) {
          notify.warning(this.$t('RESTART_PARTIAL_NO_PERMISSION', { count: skippedCount }));
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    async restartDocumentsExport() {
      const restartedIds = [...this.selectionList];
      try {
        this.processing = true;
        const response = await documentListApiService.restartExportDocuments(
          this.selectionList.join(','),
          this.restartExportedInvoices
        );
        if (response.success === false) {
          throw response;
        }
        const allSuccess = response.data.every((item: any) => item.success === true);
        if (allSuccess) {
          notify.success(this.$t('RESTART_SUCCESS'));
        } else {
          notify.error(this.$t('RESTART_EXPORTED_PARTIAL_FAILURE'));
        }
        this.headerCheckbox = false;
        this.resetAllSelectedRows();
        const successfulIds = allSuccess
          ? restartedIds
          : (response.data as any[])
              .filter((item: any) => item.success === true)
              .map((item: any) => item.doc_id || item.id)
              .filter(Boolean);
        this.applyOptimisticRestartUpdate(successfulIds);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

