    async mergeDocuments() {
      try {
        this.showLoading();

        const response: any = await documentDetailApiService.mergeDocumnet(
          this.selectionList.toString()
        );

        if (response.success === false) {
          throw response;
        }

        await this.fetchInvoices(true);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async deleteMultipalDocument() {
      if (!this.selectionList || this.selectionList.length === 0) {
        return;
      }

      // Partition the selected documents into those the user is allowed to
      // delete and those that are blocked. Blocked documents are grouped by the
      // reason they cannot be deleted (permission / exported / active
      // processing) so the user gets a message that reflects the real cause
      // instead of a blanket "insufficient permissions". Only the
      // deletable ones are sent to the API.
      const selectedRows = this.selectedDocuments;
      const deletableIds: string[] = [];
      const blockedReasons = new Set<DeleteBlockReason>();
      selectedRows.forEach((row: dynamicObj) => {
        const reason = this.deleteBlockReason(row);
        if (reason === null) {
          deletableIds.push(row.id);
        } else {
          blockedReasons.add(reason);
        }
      });
      const blockedCount = this.selectionList.length - deletableIds.length;

      if (deletableIds.length === 0) {
        // Nothing the user can delete — explain why and stop before any API call.
        notify.warning(this.$t('delete_blocked_header'), {
          description: this.buildDeleteBlockedDescription(blockedReasons),
        });
        return;
      }

      this.processing = true;
      // Show the table skeleton/shimmer for the whole delete + refresh so the
      // user gets immediate feedback instead of a frozen table during the
      // round-trip. The skeleton renders while `show_table_loader` is true and
      // there are no rows, so clear the rows up front.
      this.show_table_loader = true;
      this.display_data = [];
      let response: any;
      try {
        let paramsMap = new Map();
        paramsMap.set('doc_ids', deletableIds.join(','));
        response = await genericService.deleteRequest(
          api.delete_documents,
          paramsMap
        );

        if (response.success === false) {
          throw response;
        }

        // Report the outcome. Always show how many were deleted; when some
        // documents were skipped, add a warning that lists the actual reasons
        // (permission / exported / active processing) rather than assuming a
        // permission problem.
        notify.success(
          this.$t('delete_success_bulk', {
            deleted: deletableIds.length,
          })
        );
        if (blockedCount > 0) {
          notify.warning(
            this.$t('delete_blocked_partial', { skipped: blockedCount }),
            { description: this.buildDeleteBlockedDescription(blockedReasons) }
          );
        }

        this.headerCheckbox = false;
        this.resetAllSelectedRows();
        // loadData() rebuilds queryParams and refetches; its fetchInvoices call
        // defaults to the shimmer path, so the skeleton stays visible until the
        // fresh page arrives. Awaited so the loader is cleared only afterwards.
        await this.loadData();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        // The delete failed — pull the original list back so the user is not
        // left staring at an empty skeleton.
        await this.loadData();
      } finally {
        this.processing = false;
        this.show_table_loader = false;
      }
    },
    removeQuickFilter(key: string) {
      this.quickFilterMap.delete(key);
      this.applyFilter();
    },

    isDocRestartable(row: any): boolean {
      if (this.restartExportedInvoices) {
        return true;
      }

      const status = String(row['status']);
      if (status === 'finished') {
        return false;
      }

      if (this.isAdmin) {
        return true;
      }

      const actionRestart = this.user_settings['ACTION_RESTART'];
      if (actionRestart === 'only_admin') {
        return false;
      }
      // Assignee may be a single user (assigned_to_id) or a group
      // (assigned_to_group_id) — allow a member of the assigned group too.
      if (
        actionRestart === 'only_admin_assignee' &&
        row['assigned_to_id'] !== this.getUserId() &&
        !Acl._isAssignedGroupMember(row)
      ) {
        return false;
      }

      if (!Acl.canUpdate(row)) {
        return false;
      }

      return (
          status === 'ready_for_validation' ||
          status === 'error' ||
          status === 'export_error' ||
          Boolean(row['restart_allowed'])
      );
    },

    isDocExportRestartable(row: any): boolean {
      if (this.restartExportedInvoices) {
        return true;
      }

      const status = String(row['status']);

      if (this.user_settings['ACTION_RESTART'] == 'only_admin' && !this.isAdmin) {
        return false;
      }

      // Assignee may be a single user (assigned_to_id) or a group
      // (assigned_to_group_id) — allow a member of the assigned group too.
      if (
        this.user_settings['ACTION_RESTART'] == 'only_admin_assignee' &&
        row['assigned_to_id'] != this.getUserId() &&
        !Acl._isAssignedGroupMember(row) &&
        !this.isAdmin
      ) {
        return false;
      }

      // ACL check (admin bypass is handled inside Acl.canUpdate)
      if (!Acl.canUpdate(row)) {
        return false;
      }
      return (
          status === 'export_error' ||
          status === 'exporting' ||
          status === 'restart_export' ||
          status === 'finished'
      );
    },

    isExportErrorRestart(row: any): boolean {
      if (!Acl.canUpdate(row)) {
        return false;
      }
      const status = String(row['status']);
      const restartAllowed = Boolean(row['restart_allowed']);

      if (this.restartExportedInvoices) {
        return true;
      } else {
        return status === 'export_error' || restartAllowed == true;
      }
    },

    isDocDeleteable(row: any) {
      return this.deleteBlockReason(row) === null;
    },

    /**
     * Determine why a document cannot be deleted, or null if it can.
     *
     * Single source of truth for the delete gate — both isDocDeleteable (which
     * hides the row action) and the bulk-delete messaging use this so
     * the reason shown to the user always matches the reason the action was
     * blocked. Permission is checked first (it is the more fundamental gate),
     * then the status-based restrictions.
     *
     * @returns a DELETE_BLOCK_REASON value, or null when the document is deletable
     */
    deleteBlockReason(row: any): DeleteBlockReason | null {
      if (!Acl.canDeleteDoc(row)) {
        return DELETE_BLOCK_REASON.PERMISSION;
      }
      const status = String(row['status']);
      // A finished document has completed processing and been exported; it is
      // surfaced to the user as "exported".
      if (status === 'finished') {
        return DELETE_BLOCK_REASON.EXPORTED;
      }
      if (
        status === 'workflow' ||
        status === 'running' ||
        status === 'restart_in_progress'
      ) {
        return DELETE_BLOCK_REASON.PROCESSING;
      }
      return null;
    },

    /**
     * Build the description body for the "some documents could not be deleted"
     * warning: one bullet line per distinct block reason that actually applies.
     *
     * Returned as a VNode (one <div> per reason) rather than a string —
     * vue-sonner escapes string descriptions, so neither "\n" nor "<br />"
     * would render as a line break; separate elements lay the bullets out on
     * their own lines.
     */
    buildDeleteBlockedDescription(reasons: Set<DeleteBlockReason>) {
      const lines: string[] = [];
      if (reasons.has(DELETE_BLOCK_REASON.PERMISSION)) {
        lines.push(this.$t('delete_blocked_reason_permission'));
      }
      if (reasons.has(DELETE_BLOCK_REASON.EXPORTED)) {
        lines.push(this.$t('delete_blocked_reason_exported'));
      }
      if (reasons.has(DELETE_BLOCK_REASON.PROCESSING)) {
        lines.push(this.$t('delete_blocked_reason_processing'));
      }
      // Left-align the list (the toast itself is centered) and give each line a
      // hanging indent so a wrapped reason lines up under its text, not under
      // the bullet. The bullet is its own element so it never wraps.
      return () => h(
        'div',
        { style: { textAlign: 'left' } },
        lines.map((line) =>
          h(
            'div',
            {
              style: {
                display: 'flex',
                alignItems: 'flex-start',
                gap: '0.4em',
              },
            },
            [h('span', '•'), h('span', line)]
          )
        )
      );
    },

    isDocReassignAble(row: any) {
      const status = String(row['status']);
      return (
        Acl.canUpdate(row) &&
        status != 'finished' &&
        status != 'workflow' &&
        status != 'running' &&
        status != 'restart_in_progress'
      );
    },

    isDocDownloadable(row: any) {
      const status = String(row['status']);
      return (
        Acl.canView(row) && status != 'running' && status != 'restart_in_progress'
      );
    },

    /**
     * Check if document can be validated (edited)
     * Requires edit permission and appropriate status
     */
    isDocValidatable(row: any) {
      const status = String(row['status']);
      return (
        Acl.canEditDoc(row) &&
        status != 'finished' &&
        status != 'workflow' &&
        status != 'running' &&
        status != 'restart_in_progress' &&
        status != 'error' &&
        status != 'pending_confirmation'
      );
    },

    assignmentSuccess(e: any) {
      this.assigneDialog = false;
      if (this.selectionList) {
        this.headerCheckbox = false;
        this.resetAllSelectedRows();
      }

      this.refreshFilters({detail: {show_shimmer_loader: true, refresh_cache: true}});
      // this.resetFilters();
    },

    renderquality(row: any) {
      if (!this.user_settings['OCR_PERCENTAGE'] || !this.user_settings['OCR_PERCENTAGE']) {
        return;
      }

      let quality = '';
      if (row.hasOwnProperty('quality')) {
        let name = this.$t('overall');
        const item = row['quality'];
        if (parseInt(row['quality']) < parseInt(this.user_settings['OCR_PERCENTAGE'])) {
          quality = name + ' : <FONT COLOR="#AA0500">' + row['quality'] + '</FONT COLOR>'
        }
        if (parseInt(item) == parseInt(this.user_settings['OCR_PERCENTAGE'])) {
          quality = name + ' : <FONT COLOR="#ffff00">' + row['quality'] + '</FONT COLOR>'
        }
        if (parseInt(item) > parseInt(this.user_settings['OCR_PERCENTAGE'])) {
          quality = name + ' : <FONT COLOR="#00ff00">' + row['quality'] + '</FONT COLOR>'
        }
      }
      return quality;
