    // Reports the outcome so loadDashboardData knows whether to retry over
    // HTTP: 'delivered' | 'stale' | 'invalid' | 'failed'.
    async getWebSocketDashboard(fetchGeneration = this.dashboardFetchGeneration): Promise<string> {
      try {
        const dashboard_filter_request = {
          type: 'dashboard',
        } as dynamicObj;

        dashboard_filter_request['data'] = {} as dynamicObj;
        let queryParams = this.queryParams;
        queryParams = queryParams.replace('?', '');
        const queryParamsAsArray = queryParams.split('&');
        queryParamsAsArray.forEach((item: any) => {
          item = item.split('=');
          if (item.length === 2) {
            // Values are URL-encoded for the HTTP path (makeQueryParamFromFilters
            // wraps filter_predicates in encodeURIComponent to protect the '='
            // characters inside the JSON). The WebSocket path doesn't go through
            // an HTTP decoder, so we decode here before shipping the dict.
            // Applied to every value so the WS contract matches HTTP semantics.
            let value = item[1];
            try {
              value = decodeURIComponent(value);
            } catch {
              // Leave as-is if decoding throws on a malformed byte sequence.
            }
            dashboard_filter_request.data[item[0]] = value;
          }
        });

        this.data_status = 'fetching';
        this.dashboard_data_flag = false;
        const result = await this.sendMessageToSocket(
          dashboard_filter_request.type,
          dashboard_filter_request.data
        );

        if (this.dashboardFetchGeneration !== fetchGeneration) {
          return 'stale';
        }
        this.updateDocumentStats(result);
        this.updateTableData(result);
        clearErrorSource('dashboard:invoices:ws');
        clearErrorSource('dashboard:invoices:http');
        return 'delivered';
      } catch (err) {
        // Bug-31 (2026-04-24): the WebSocket path used to unconditionally
        // fall back to REST via handleWebsocketDelay() — but a 422 from
        // an invalid raw_query will 422 again on REST, producing the
        // double-toast + retry-loop the user reported. Short-circuit
        // here: validation errors are NOT a transport issue, no fallback
        // can rescue them, the user sees the inline chip-editor banner.
        if (isQueryValidationError(err)) {
          this.emitQuerySemanticError(err);
          this.show_table_loader = false;
          this.data_status = 'received';
          return 'invalid';
        }
        this.disableWebsocketAndReconnect();
        return 'failed';
      } finally {
        if (this.dashboardFetchGeneration === fetchGeneration) {
          this.show_table_loader = false;
        }
      }
    },

    hasPreviewFile (row: any) {
      if (row.hasOwnProperty('preview_file_path') && row['preview_file_path']) {
        return true;
      }
      return false;
    },

    downloadPreviewFile (row: any) {
      try {
        if (!row['preview_file_path']) {
          return;
        }
        let path = DOC2API_URL + '/' + row['preview_file_path'] + '?' + this.tokenQueryParam;
        if (!path) {
          return;
        }

        var link = document.createElement('a');
        link.download = row['filename'];
        link.href = path;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      } catch (err) {
        logError(err);
      }
    },
