      rowElement.classList.remove('light-duplicate-invoice-background')
    },
    highlightRowForDuplicateInvoice(row: any) {
      this.removeOldHighlight(this.highlightedRow)
      this.highlightedRow = row.id;
      const rowElement = document.getElementById('row_' + row.id)
      if (!rowElement) {
