    },
    async proceedToDuplicateInvoices(row: any) {
      if (this.selectedDocIdWfLog) {
        const oldWfRow = document.getElementById('row_' + this.selectedDocIdWfLog) as HTMLElement;
        if (oldWfRow) oldWfRow.classList.remove('light-grey-with-effect');
        this.selectedDocIdWfLog = '';
      }

      // Dashboard rows only carry a lightweight duplicate marker for
      // performance. Load the complete duplicate list on demand when the user
      // opens the panel.
      let documentIds = row.duplicates || [];
      let duplicateInvoices = row.related_supplier_invoices;
      try {
        this.showLoading();
        const queryParams = [
          `doc_id=${encodeURIComponent(row.id)}`,
          `doc_type=${encodeURIComponent(row.doc_type)}`,
          'include_supplier_invoice=true',
          'legacy_format=false',
        ].join('&');
        const response = await documentListApiService.getDuplicateInvoices(
          `?${queryParams}`,
        );
        documentIds = response?.duplicate_documents || documentIds;
        duplicateInvoices =
          response?.supplier_invoice_duplicates || duplicateInvoices;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }

      this.duplicateDocumentIds = documentIds.join(',');
      this.duplicateInvoiceList = duplicateInvoices;
      this.keyToUpdate++;
      this.highlightRowForDuplicateInvoice(row)
      this.toggleSplitter();
    },
    toggleSplitter() {
      this.isDuplicatePanel = true;
      this.splitterModel = 50;
      this.wfLogOpen = false;
      this.adjustTableHeightForDuplicate()
    },
    closeSpliter() {
