    applyCounterFilters(params: any) {
      this.quickFilterMap.clear();
      this.quickFilterMap.set('status', params.detail.status + ',');
      if (params.detail.status !== 'all') {
        this.quickFilterMap.set('status_list', [{
          value: params.detail.status,
          label: this.getLabelTranslation(params.detail.status),
        }]);
      }
      this.applyFilter();
    },

    adjustTableHeightForDuplicate() {
      const splitterRef = this.$refs.splitter as any;
      if (!splitterRef) return;

      const splitterEl = splitterRef.$el || splitterRef;
      const splitterBefore = splitterEl.querySelector('.q-splitter__before') as HTMLElement | null;
      const splitterAfter = splitterEl.querySelector('.q-splitter__after') as HTMLElement | null;
      if (!splitterBefore) return;

      nextTick(() => {
        // Calculate available height for main table: splitter before section minus tabs height (~48px)
        const tabsHeight = 48;
        const availableHeight = splitterBefore.clientHeight - tabsHeight;
        this.tableHeight = `${Math.max(availableHeight, 200)}px`; // Minimum 200px

        // Calculate available height for duplicate panel table
        if (splitterAfter && this.isDuplicatePanel) {
          // Account for expansion header (~48px), card padding (~32px), and some buffer
          const expansionHeaderHeight = 48;
          const cardPadding = 32;
          const buffer = 20;
          const duplicateAvailableHeight = splitterAfter.clientHeight - expansionHeaderHeight - cardPadding - buffer;
          this.duplicateTableHeight = `${Math.max(duplicateAvailableHeight, 80)}px`; // Minimum 80px
        }
      });
    },

    resetDropZone() {
      this.dragDepth = 0;
      const element = document.getElementById('drop-zone');
      if (element) {
        element.classList.remove('drop-zone', 'active-top', 'active-bottom');
      }
    },
    
    handleWindowDragLeave(e: { clientX: number; clientY: number; }) {
    // If the mouse leaves the viewport, hide the overlay
      if (
        e.clientX <= 0 ||
        e.clientY <= 0 ||
        e.clientX >= window.innerWidth ||
        e.clientY >= window.innerHeight
      ) {
        this.resetDropZone();
      }
    },

    async loadSelectedDashboardPreference() {
      const response = await this.getUserBasedSettings(this.selected_dashboard_pref_key);
      logger.debug('[Dashboard Debug] selected_dashboard_pref_key response:', response);

      if (response && response !== 'undefined' && response !== 'null') {
        try {
          this.selected_dashboard = JSON.parse(response);
          // Apply dashboard's page count, fallback to user preference if not set
          if (this.selected_dashboard?.customizations?.dashboard_page_count) {
            this.pagination_size = this.selected_dashboard.customizations.dashboard_page_count;
          } else {
            // Dashboard doesn't have page count, load from user preferences
            await this.getPaginationSize();
          }
        } catch (err) {
          this.selected_dashboard = null; // Safe fallback
        }
      } else {
        logger.debug('[Dashboard Debug] No valid selected_dashboard preference found');
        this.selected_dashboard = null;
      }
    },
  },
