      completed,
      processing,
      in_progress,
      columns_key,
      all_invoices,
      notifyUpdate,
      tempFilterMap,
      show_analytics,
      quickFilterMap,
      pagination_size,
      pagination_size_key,
      paginationCount,
      filtered_columns,
      manually_processed,
      current_invoice_count,
      automatically_processed,
      validated_pending_approval,
      approved_pending_second_approval,
      show_loading_times,
      upload_classify_doctype,
      isTabDragging,
      isColumnDragging,
      selected_dashboard,
      selectedGroupByState,
      order_by,
    } = storeToRefs(dashboard_store);
    const {
      getSavedFilters,
      removeSavedFilters,
      saveFilters,
      handleTableColumns,
      makeQueryParamFromFilters,
      setDefaultFilters,
      getSavedColumns,
      getOrderBy,
      getColumnLabel,
      saveSortedColumns,
      getPaginationCount,
      getPaginationSize,
      setPaginationSize,
      fetchAndHandleTableColumns,
      saveOrderBy,
      isDashboardSelected,
      checkForDashboardUpdates,
    } = dashboard_store;

    const settings_store = useSettingStore();
    const { user_settings, execute_auto_export } = storeToRefs(settings_store);
    const { startSettingsFetch, getUserBasedSettings } = settings_store;

    const websocket_store = useWebSocketStore();
    const { dashboard_data, isConnected, hasError:websocketHasError, dashboard_data_flag, dashboard_update, dashboard_update_flag } = storeToRefs(websocket_store);
    const {
      subscribeToChannel,
      unsubscribeToChannel,
      sendMessageByType: sendMessageToSocket,
    } = websocket_store;

    const users_store = useDropdownStore();
    const { prepareUsersDropdown } = users_store
    const { usersList } = storeToRefs(users_store)

    const user_store = useUserStore();
    const { isMediUser ,getProfile, getUserId} = user_store;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    const doc_attribute_store = useDocAttributesStore();
    const { getDocTypeAllSettings } = doc_attribute_store;
   
