/**
 * Dashboard fetch error classification — shared helper (Bug-31, 2026-04-24).
 *
 * When the user types an invalid `raw_query` (unknown field, syntax
 * error, etc.), the backend returns 422. Surfacing this as the generic
 * "Error while fetching documents" toast is misleading — the docs are
 * fine, the QUERY is invalid. The chip editor's inline validation banner
 * already communicates the exact cause of the validation failure, so a
 * duplicate toast is pure noise.
 *
 * Use `isQueryValidationError(err)` in every dashboard fetch catch block
 * (both REST and WebSocket paths). When it returns true, SKIP the toast
 * — the user will see the inline banner in the chip editor. For anything
 * that isn't a validation error (network, 5xx, timeout, WebSocket
 * disconnect), fall through to the usual `notify.error` flow.
 *
 * Why this is a helper and not inline:
 *   - Two paths to dashboard-fetch-error exist (REST in dashboard.vue
 *     fetchInvoices, WebSocket in sendDashboardWebsocketRequest) and both
 *     need the same classification.
 *   - Error shapes differ between the two paths. Keeping the shape-sniffing
 *     logic in one place means a bug fix (e.g. adding support for a new
 *     backend error envelope) only touches one file.
 *   - The regex fallback is conservative — matches specific strings the
 *     backend emits for validation failures, so random WebSocket errors
 *     (disconnect, timeout) don't get accidentally suppressed.
 */

type Maybe<T> = T | null | undefined;

// Shape of an axios-style error. Partial because we only touch a few
// fields and we want to stay defensive against different HTTP clients.
interface HttpLikeError {
  response?: {
    status?: number;
    data?: {
      detail?: unknown;
      message?: unknown;
      error?: unknown;
    };
  };
  status?: number;
  statusCode?: number;
  code?: number | string;
  error_code?: number | string;
  data?: {
    detail?: unknown;
    message?: unknown;
    error?: unknown;
  };
  detail?: unknown;
  error?: unknown;
  message?: unknown;
}

/**
 * Return true when `err` looks like a query-validation error from the
 * dashboard fetch (REST or WebSocket). Callers should skip the
 * "Error while fetching documents" toast when this is true — the chip
 * editor's inline banner is the authoritative signal.
 */
export function isQueryValidationError(err: Maybe<unknown>): boolean {
  if (!err || typeof err !== 'object') return false;
  const e = err as HttpLikeError;

  // HTTP error wrappers — axios keeps status under response.status,
  // native fetch wrappers usually at the root. Some libs use statusCode.
  const status = e?.response?.status ?? e?.status ?? e?.statusCode;
  if (status === 422 || status === 400) return true;

  // WebSocket payload shape (custom backend error — sent as a message,
  // not an HTTP response). The socket-client forwards the backend's
  // `code` / `error_code` field on the rejected promise.
  const code = e?.code ?? e?.error_code;
  if (code === 422 || code === 400 || code === '422' || code === '400') {
    return true;
  }

  // Free-text signal — check every known location where a validation
  // error message could land. This is the fallback when the transport
  // strips status codes (some proxies do that, and some WebSocket
  // implementations surface the error as a plain string).
  const haystack = [
    e?.message,
    e?.response?.data?.detail,
    e?.response?.data?.message,
    e?.response?.data?.error,
    e?.data?.detail,
    e?.data?.message,
    e?.data?.error,
    e?.detail,
    e?.error,
  ]
    .map((x) => String(x ?? ''))
    .join(' ');

  // Narrow pattern — explicit backend error strings only. We do NOT
  // match the generic word "error" because almost every error message
  // includes it; that would cause us to swallow real failures too.
  return /invalid raw_query|unknown field|syntax error|validation error|unprocessable entity|raw_query.*invalid/i.test(
    haystack,
  );
}
