<template>
  <q-tabs
    v-model="selected_doc_type_tab"
    indicator-color="transparent"
    dense
    align="left"
    class="text-color tab-container"
    :breakpoint="0"
    inline-label
  >
    <template
      v-for="(doc_type, index) in visibleDocTypes"
      :key="doc_type.value"
    >
      <q-tab
        :draggable="true"
        @dragstart="onTabDragStart($event, visibleDocTypes, index)"
        @drop.prevent="handleTabDrop($event, index, saveTabs)"
        @dragover.prevent="onTabDragOver($event, index)"
        @dragenter.prevent="onTabDragEnter"
        @dragleave.prevent="onTabDragLeave"
        @click="tabSelected(doc_type)"
        :name="doc_type.value"
        :data-test="`doc-type-tab-${doc_type.value}`"
        class="doc-type-tab small-shadow back-white text-color"
        v-if="isExcludedFromList(doc_type.name)"
        :class="
          doc_type.value == selected_doc_type_tab
            ? 'bg-primary small-shadow text-white  inset-shadow-down'
            : ''
        "
      >
        <template v-slot:default>
          <q-icon name="drag_indicator" class="drag-icon no-padding"></q-icon>
          <span class="tab-label">{{ displayDocType(doc_type.name) }}</span>
          <q-icon
            v-if="doc_type.value !== 'all'"
            name="close"
            color="negative"
            class="remove-icon"
            @click.stop.prevent="toggleDocType(doc_type)"
          >
            <q-tooltip>{{ $t('remove') }}</q-tooltip>
          </q-icon>
          <q-tooltip>{{ displayDocType(doc_type.name) }}</q-tooltip>
        </template>
        <!-- <q-separator vertical class="q-ml-sm separator" /> -->
      </q-tab>
    </template>
    <q-btn
      flat
      class="small-shadow doc-type-tab text-color back-white"
      color="primary"
      icon="add"
    >
      <q-menu anchor="bottom middle" self="top middle" :offset="[0, 5]">
        <q-list dense>
          <template
            v-for="doc_type in active_doc_type_list"
            :key="doc_type.value"
          >
            <q-item
              clickable
              @click="toggleDocType(doc_type)"
              v-if="isExcludedFromList(doc_type.name)"
              :active="isAlreadySelected(doc_type.value)"
            >
              <span class="q-mt-xs">{{ displayDocType(doc_type.name) }}</span>
            </q-item>
          </template>
        </q-list>
      </q-menu>
    </q-btn>
  </q-tabs>
</template>
<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import docTypeLable from 'src/utils/docTypeLable';
import dragDropDocType from 'src/mixins/dragDropDocType';
import {
  sorted_doc_type_tabs_pref_key,
  excluded_doctype_tabs,
} from 'src/constants';
import {
  useDropdownStore,
  useDashboardStore,
  useSettingStore,
} from 'src/store/main';

export default defineComponent({
  mixins: [dragDropDocType, docTypeLable],
  data(): { isFromMount: boolean; stopWaitingForDocType: (() => void) | null } {
    return {
      isFromMount: false,
      // Handle returned by `$watch` in mounted() — kept so we can
      // tear it down on unmount (defence against leaking watchers
      // if the component is destroyed before doc_type ever arrives)
      // and nulled out once we've consumed the first valid arrival.
      stopWaitingForDocType: null,
    };
  },
  mounted() {
    this.prepareTabs();
    this.selectDocTypeFromMap();

    this.$nextTick(() => {
      this.isFromMount = true;
      this.dashboard_updated = false;
    });

    document.addEventListener('remove_selected_tab', this.resetTab);
    document.addEventListener('apply_tabs_filter', this.setSavedTab);
    // DOCB-11199 #3 (follow-up): Vue mounts children BEFORE parents,
    // so docTypeTabs.vue:mounted runs while `dashboard.vue:mounted`
    // is still mid-await — meaning `quickFilterMap` is empty at the
    // synchronous `selectDocTypeFromMap()` call above, and the
    // persisted doc_type never gets applied. Wait for it to appear
    // and restore once. One-shot: we only care about the FIRST
    // arrival (hydration from LocalStorage); later mutations go
    // through user-driven paths (tabSelected / overWriteFilters /
    // apply_tabs_filter event) that already wire the UI.
    this.stopWaitingForDocType = this.$watch(
      () => this.quickFilterMap.get('doc_type'),
      (docType: any) => {
        if (docType && docType.value) {
          this.selected_doc_type_tab = docType.value;
          this.stopWaitingForDocType?.();
          this.stopWaitingForDocType = null;
        }
      },
    );
  },
  unmounted() {
    document.removeEventListener('remove_selected_tab', this.resetTab);
    document.removeEventListener('apply_tabs_filter', this.setSavedTab);
    this.stopWaitingForDocType?.();
    this.stopWaitingForDocType = null;
  },
  methods: {
    // Ensure the 'All' tab is always present and cannot be removed
    resetTab() {
      this.selected_doc_type_tab = '';
    },
    isExcludedFromList(name: string) {
      return !excluded_doctype_tabs.includes(name);
    },
    isAlreadySelected(value: string) {
      return !!this.visibleDocTypes.some(
        (doc_type: any) => doc_type.value == value,
      );
    },
    toggleDocType(doc_type: dynamicObj) {
      if (!doc_type) {
        return;
      }

      // Do not allow toggling/removing the 'All' tab
      if (doc_type.value === 'all') {
        return;
      }

      if (this.isAlreadySelected(doc_type.value)) {
        const doc_type_index = this.visibleDocTypes.findIndex(
          (dt: any) => dt.value == doc_type.value,
        );
        this.visibleDocTypes.splice(doc_type_index, 1);
        this.saveTabs();

        if (this.selected_doc_type_tab === doc_type.value) {
          //Check if only all is remainin to highlight it.
          this.selected_doc_type_tab = 'all';
          this.quickFilterMap.delete('doc_type');
          const event = new CustomEvent('apply_filters', { detail: {} });
          document.dispatchEvent(event);

          //On Tab Removal show update dashboard button as now tab value is all
          this.checkForDashboardUpdates();
        }
        return;
      }

      this.visibleDocTypes.push(doc_type);
      this.saveTabs();
    },
    saveTabs() {
      this.setUserPreferences(
        sorted_doc_type_tabs_pref_key,
        JSON.stringify(this.visibleDocTypes),
      );
    },
    tabSelected(doc_type: dynamicObj) {
      if (!doc_type) {
        return;
      }
      if (doc_type.value == 'all') {
        this.quickFilterMap.delete('doc_type');
        const event = new CustomEvent('apply_filters', { detail: {} });
        document.dispatchEvent(event);
        if (this.isFromMount) {
          this.checkForDashboardUpdates();
        }
        return;
      }
      this.quickFilterMap.set('doc_type', doc_type);
      this.selected_doc_type_tab = doc_type.value;
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
      this.checkForDashboardUpdates();
    },
    selectDocTypeFromMap() {
      console.log(this.quickFilterMap.get('doc_type'), 'selected doc type on mount');
      if (this.quickFilterMap.get('doc_type')) {
        this.selected_doc_type_tab = this.quickFilterMap.get('doc_type').value;
        // this.tabSelected(this.quickFilterMap.get('doc_type'))
      } else {
        // DOCB-11199 #3 follow-up: explicitly mark 'all' as active
        // on mount when no doc_type has been persisted. `tabSelected`
        // for 'all' returns early without touching
        // `selected_doc_type_tab`, so without this assignment the
        // tab bar rendered with no visual "active" pill on a fresh
        // load. The mount used to paper over this by setting
        // `selected_doc_type_tab = 'all'` unconditionally, which
        // clobbered the persisted-tab restore path above.
        this.selected_doc_type_tab = 'all';
        this.tabSelected(this.default_selected_doc_type);
      }
    },
    prepareTabs() {
      if (this.user_based_settings[sorted_doc_type_tabs_pref_key]) {
        this.visibleDocTypes = JSON.parse(
          this.user_based_settings[sorted_doc_type_tabs_pref_key],
        );
      }

      // Ensure 'All' is always in the visible tabs (as the first tab)
      const hasAll = this.visibleDocTypes.some((dt: any) => dt.value === 'all');
      if (!hasAll) {
        const allDocTypesObj = {
          label: this.$t('all'),
          value: 'all',
          name: 'all',
        };
        this.visibleDocTypes.unshift(allDocTypesObj);
      }

      this.default_selected_doc_type = JSON.parse(
        JSON.stringify(this.visibleDocTypes[0]),
      );
    },

    setSavedTab(event: any) {
      this.selected_doc_type_tab =
        event.detail.filters && event.detail.filters.get('doc_type')
          ? event.detail.filters.get('doc_type').value
          : 'all';

      if (this.selected_doc_type_tab === 'all') {
        this.quickFilterMap.delete('doc_type');
      } else {
        const doc_type = this.visibleDocTypes.find(
          (dt: any) => dt.value === this.selected_doc_type_tab,
        );
        this.quickFilterMap.set('doc_type', doc_type);
      }
    },
  },
  setup() {
    const users_store = useDropdownStore();
    const { active_doc_type_list } = storeToRefs(users_store);

    const setting_store = useSettingStore();
    const { setUserPreferences } = setting_store;
    const { user_based_settings } = storeToRefs(setting_store);

    const dashboard_store = useDashboardStore();
    const { checkForDashboardUpdates } = dashboard_store;
    const { quickFilterMap, dashboard_updated } = storeToRefs(dashboard_store);

    return {
      setUserPreferences,
      user_based_settings,
      active_doc_type_list,
      quickFilterMap,
      default_selected_doc_type: ref({} as any),
      visibleDocTypes: ref([] as any),
      selected_doc_type_tab: ref(''),
      maxTabLimit: ref(7),
      checkForDashboardUpdates,
      dashboard_updated,
    };
  },
});
</script>

