// DOCB-13856: prefer the API's resolved List-of-Values label for display.
//
// Documents store the canonical LOV value ("Invoice"); the customer's
// per-language label lives in a separate translations table. The dashboard API
// resolves it server-side and ships it as a sibling `<field>_label` key, so the
// column can show "Rechnung" while the row still carries "Invoice".
//
// Display only — sorting, filtering, search and export continue to use the
// canonical value. A column with no List of Values (or a value with no
// translation for the active language) has no `_label` key and renders exactly
// as before.

export const LOV_LABEL_SUFFIX = '_label';

// Fields whose label the client must IGNORE outright.
//
// `doc_type` and `status` are translated client-side from the canonical value
// (displayDocType / getLabelTranslation resolve shipped i18n keys), and neither
// is LOV-backed. Cells never reach here — both have their own body-cell slot —
// but the group-row builders call lovLabel() with whatever field the user
// grouped by, and formatGroupValue() then hands the result to those same
// helpers. Passing an already-translated string would fail to resolve, so the
// label is dropped before it can reach them.
//
// NOTE this is *not* the same as "has a client-side translation path". A field
// can have one as a FALLBACK and still want its LOV label to win — that is what
// the `fallback` parameter below is for. Only fields that must never accept a
// label belong in this set.
const LABEL_IGNORED_FIELDS: ReadonlySet<string> = new Set([
  'doc_type',
  'status',
]);

/**
 * Display value for `field` on `row`.
 *
 * Precedence: the API-resolved LOV label (the only source for values a customer
 * added themselves) → `fallback(raw)` when supplied → the raw stored value.
 *
 * `fallback` exists for fields whose canonical values also map to shipped i18n
 * keys — e.g. invoice_sub_type, where "Cost Invoice" has a `cost_invoice` key.
 * An org with no LOV configured keeps that translation; an org with one gets
 * its own label instead.
 */
export function lovLabel(
  row: any,
  field: string,
  fallback?: (raw: string) => string,
): any {
  if (!row || !field) return undefined;

  const raw = row[field];
  if (LABEL_IGNORED_FIELDS.has(String(field).toLowerCase())) {
    return raw;
  }

  const label = row[`${field}${LOV_LABEL_SUFFIX}`];
  // Only a non-empty string counts — an empty or non-string `_label` must not
  // blank out a value the user would otherwise see.
  if (typeof label === 'string' && label) return label;

  // Fallback only applies to a real value; an empty cell stays empty so the
  // table's own `|| '-'` handling still shows a dash.
  if (fallback && raw !== null && raw !== undefined && raw !== '') {
    return fallback(String(raw));
  }
  return raw;
}
