<template>
  <q-card class="loading-time-popup sticky-header">
    <q-toolbar class="bg-primary text-white">
      <q-toolbar-title>
        <span> Dashboard Loading Times</span>
      </q-toolbar-title>
      <q-btn flat round dense class="primary" icon="close" v-close-popup />
    </q-toolbar>
    <DocBitsTable
      :rows="tableRows"
      :columns="columns"
      row-key="key"
      table-id="loading_times_table"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: false,
        pagination: false,
        columnReorder: false,
      }"
      no-data-label="no_record_found"
      flat-style
    />
    <q-toolbar class="bg-grey-8 text-white">
      <q-toolbar-title>
        <span> Total Time Spent: </span
        ><span class="total-time"> {{ total_time_spend }} </span>
      </q-toolbar-title>
    </q-toolbar>
  </q-card>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useDashboardStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  mixins: [],
  components: { DocBitsTable },
  props: {
    detailedTimeSpent: {
      type: Object,
      value: null,
    },
  },
  data() {
    return {
      processedData: {} as any,
      columns: [
        { name: 'key', label: 'Services', field: 'key', align: 'left' },
        { name: 'value', label: 'Loading Times', field: 'value', align: 'right', classes: 'time-column' },
      ] as UnifiedTableColumn[],
    };
  },
  computed: {
    tableRows() {
      return Object.entries(
        this.detailedTimeSpent?.detailed_time_spent ?? {},
      ).map(([key, value]) => ({
        key: key
          .split('_')
          .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
          .join(' '),
        value: parseFloat(((value as number) * 1000).toFixed(2)) + ' ms', //convert to ms and format
      }));
    },
    total_time_spend() {
      return (
        (parseFloat((this.detailedTimeSpent?.time_spent * 1000).toFixed(2)) ||
          0) + ' ms'
      );
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const { show_loading_times } = storeToRefs(dashboard_store);

    return {
      show_loading_times,
    };
  },
});
</script>
