<template>
  <q-card class="card-element">
    <q-toolbar class="bg-primary text-white">
      <q-toolbar-title>
        <span>{{ $t('export_history') }}</span>
      </q-toolbar-title>
      <q-btn
        flat
        round
        dense
        class="primary"
        icon="close"
        v-close-popup
      />
    </q-toolbar>

    <!-- Loading State -->
    <div v-if="loading" class="q-pa-lg text-center">
      <q-spinner-dots color="primary" size="40px" />
      <div class="q-mt-sm text-grey-6">{{ $t('loading') }}...</div>
    </div>

    <!-- Empty State -->
    <div v-else-if="exportLogs.length === 0" class="q-pa-lg text-center">
      <q-icon name="inbox" size="48px" color="grey-5" />
      <div class="q-mt-sm text-grey-6">{{ $t('no_export_history') }}</div>
    </div>

    <!-- Export Logs Table with Expandable Rows -->
    <q-table
      v-else
      :rows="exportLogs"
      :columns="tableColumns"
      row-key="id"
      hide-bottom
      flat
      :rows-per-page-options="[0]"
      class="sticky-header document-logs-container"
    >
      <!-- Custom body to handle expandable rows -->
      <template v-slot:body="props">
        <!-- Main Data Row -->
        <q-tr :props="props" class="data-row">
          <q-td
            v-for="col in props.cols"
            :key="col.name"
            :props="props"
          >
            <!-- Response column with copy/expand buttons -->
            <template v-if="col.name === 'response'">
              <div class="response-cell-wrapper">
                <code class="response-code">{{ truncateResponse(props.row.response) }}</code>
                <div v-if="props.row.response && props.row.response !== '-'" class="response-actions">
                  <!-- Expand/Collapse Button -->
                  <q-btn
                    flat
                    dense
                    round
                    size="sm"
                    :icon="expandedRows[props.row.id] ? 'expand_less' : 'expand_more'"
                    color="grey-6"
                    @click.stop="toggleExpand(props.row.id)"
                  >
                    <q-tooltip>{{ expandedRows[props.row.id] ? $t('collapse') : $t('expand') }}</q-tooltip>
                  </q-btn>
                </div>
              </div>
            </template>

            <!-- Exported On column with date formatting -->
            <template v-else-if="col.name === 'exported_on'">
              <span class="font-size-16-imp">
                {{ formatDateAccordingToPreference(props.row.exported_on) }}
              </span>
            </template>

            <!-- Status column with badge -->
            <template v-else-if="col.name === 'status'">
              <q-badge
                size="md"
                :color="getStatusColor(props.row.status)"
                :label="props.row.status"
              />
            </template>

            <!-- Default column rendering -->
            <template v-else>
              {{ col.value || '-' }}
            </template>
          </q-td>
        </q-tr>

        <!-- Expanded Row for JSON Response -->
        <q-tr
          v-if="expandedRows[props.row.id]"
          class="expanded-row"
        >
          <q-td colspan="100%" class="expanded-cell">
            <div class="expanded-content">
              <div class="expanded-header">
                <span class="expanded-label">{{ getResponseType(props.row.rawResponse) }}</span>
                <q-btn
                  flat
                  dense
                  size="sm"
                  :icon="copiedId === props.row.id + '-expanded' ? 'check' : 'content_copy'"
                  :label="copiedId === props.row.id + '-expanded' ? $t('copied') : $t('copy')"
                  :color="copiedId === props.row.id + '-expanded' ? 'positive' : 'primary'"
                  @click="copyRawResponse(props.row)"
                />
              </div>
              <pre class="response-pre">{{ formatResponseForDisplay(props.row.rawResponse) }}</pre>
            </div>
          </q-td>
        </q-tr>
      </template>
    </q-table>
  </q-card>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import dateUtils from 'src/utils/date';
import { copyToClipboard } from 'quasar';
import type { QTableColumn } from 'quasar';
import { exportApiService } from 'src/services';
import MaterialIconSet from 'quasar/icon-set/material-icons';

MaterialIconSet.table.arrowUp = 'arrow_drop_down';

export default defineComponent({
  name: 'ExportHistoryPopup',
  mixins: [dateUtils],
  props: {
    docId: {
      type: String,
      required: true,
    },
  },
  data() {
    return {
      loading: false,
      exportLogs: [] as {
        id: string;
        title: string;
        export_method: string;
        application: string;
        response: string;
        rawResponse: string;
        exported_on: string;
        status: string;
      }[],
      expandedRows: {} as Record<string, boolean>,
      copiedId: null as string | null,
    };
  },
  computed: {
    tableColumns(): QTableColumn[] {
      return [
        {
          name: 'title',
          label: this.$t('title') as string,
          field: 'title',
          align: 'left',
          sortable: true,
        },
        {
          name: 'export_method',
          label: this.$t('export_method') as string,
          field: 'export_method',
          align: 'left',
          sortable: true,
        },
        {
          name: 'application',
          label: this.$t('application') as string,
          field: 'application',
          align: 'left',
          sortable: true,
        },
        {
          name: 'response',
          label: this.$t('response') as string,
          field: 'response',
          align: 'left',
          sortable: false,
        },
        {
          name: 'exported_on',
          label: this.$t('exported_on') as string,
          field: 'exported_on',
          align: 'left',
          sortable: true,
        },
        {
          name: 'status',
          label: this.$t('status') as string,
          field: 'status',
          align: 'left',
          sortable: true,
        },
      ];
    },
  },
  watch: {
    docId() {
      this.loadExportLogs();
    },
  },
  mounted() {
    this.loadExportLogs();
  },
  methods: {
    async loadExportLogs() {
      if (!this.docId) return;

      this.loading = true;
      try {
        const response = await exportApiService.getExportLogs(this.docId, {
          includeSkipped: true,
          includeDeleted: false,
          limit: 100,
          offset: 0,
        });

        if (response && response.export_logs) {
          this.exportLogs = response.export_logs.map((log: any, index: number) => ({
            // Create unique ID combining config_id, timestamp and index to handle duplicates
            id: log.id || `${log.export_config_id}-${log.exported_on}-${index}`,
            title: log.title || '-',
            export_method: log.export_method || '-',
            application: log.export_application || '-',
            response: this.parseResponsePreview(log.export_response),
            rawResponse: log.export_response || '',
            exported_on: log.exported_on,
            status: this.mapStatus(log.export_status),
          }));
        }
      } catch (err) {
        console.error('Error loading export logs:', err);
        this.exportLogs = [];
      } finally {
        this.loading = false;
      }
    },

    parseResponsePreview(response: string | null): string {
      if (!response) return '-';

      // Try to parse JSON response - show truncated JSON string
      try {
        JSON.parse(response);
        // It's valid JSON, show truncated version
        const truncated = response.length > 40 ? response.substring(0, 37) + '...' : response;
        return truncated;
      } catch {
        // Not JSON, check if it's XML
        if (response.trim().startsWith('<?xml') || response.trim().startsWith('<')) {
          return response.substring(0, 40) + (response.length > 40 ? '...' : '');
        }
        // Plain text
        return response.length > 40 ? response.substring(0, 37) + '...' : response;
      }
    },

    isJsonResponse(response: string): boolean {
      if (!response) return false;
      try {
        JSON.parse(response);
        return true;
      } catch {
        return false;
      }
    },

    isXmlResponse(response: string): boolean {
      if (!response) return false;
      const trimmed = response.trim();
      return trimmed.startsWith('<?xml') || (trimmed.startsWith('<') && trimmed.endsWith('>'));
    },

    getResponseType(response: string): string {
      if (!response) return 'PLAIN TEXT RESPONSE';
      if (this.isJsonResponse(response)) return 'JSON RESPONSE';
      if (this.isXmlResponse(response)) return 'XML RESPONSE';
      return 'PLAIN TEXT RESPONSE';
    },

    formatResponseForDisplay(response: string): string {
      if (!response) return '-';

      // Try JSON formatting
      try {
        const parsed = JSON.parse(response);
        return JSON.stringify(parsed, null, 2);
      } catch {
        // Not JSON, try XML/HTML formatting
        if (this.isXmlResponse(response)) {
          return this.formatXml(response);
        }
        return response;
      }
    },

    formatXml(xml: string): string {
      // Simple XML/HTML formatter with indentation
      let formatted = '';
      let indent = 0;
      const tab = '  ';

      // Remove existing whitespace between tags
      const cleanXml = xml.replace(/>\s*</g, '><').trim();

      // Split by tags
      const parts = cleanXml.split(/(<[^>]+>)/g).filter(part => part.trim());

      for (const part of parts) {
        if (part.startsWith('</')) {
          // Closing tag - decrease indent before
          indent = Math.max(0, indent - 1);
          formatted += tab.repeat(indent) + part + '\n';
        } else if (part.startsWith('<?') || part.startsWith('<!')) {
          // Declaration or DOCTYPE
          formatted += part + '\n';
        } else if (part.startsWith('<') && part.endsWith('/>')) {
          // Self-closing tag
          formatted += tab.repeat(indent) + part + '\n';
        } else if (part.startsWith('<')) {
          // Opening tag
          formatted += tab.repeat(indent) + part + '\n';
          indent++;
        } else {
          // Text content
          const trimmedPart = part.trim();
          if (trimmedPart) {
            formatted += tab.repeat(indent) + trimmedPart + '\n';
          }
        }
      }

      return formatted.trim();
    },

    mapStatus(status: string): string {
      const statusMap: Record<string, string> = {
        'SUCCESS': 'Success',
        'FAIL': 'Error',
        'SKIPPED': 'Skipped',
        'PENDING': 'Pending',
      };
      return statusMap[status] || status;
    },

    getStatusColor(status: string): string {
      const colorMap: Record<string, string> = {
        'Success': 'green-2B9D73',
        'Error': 'red-13',
        'Skipped': 'grey-6',
        'Pending': 'warning',
      };
      return colorMap[status] || 'grey-6';
    },

    truncateResponse(response: string): string {
      if (!response || response === '-') return '-';
      if (response.length <= 40) return response;
      return response.substring(0, 37) + '...';
    },

    toggleExpand(rowId: string) {
      this.expandedRows[rowId] = !this.expandedRows[rowId];
    },

    async copyRawResponse(row: { id: string; rawResponse: string }) {
      try {
        await copyToClipboard(row.rawResponse);
        this.copiedId = row.id + '-expanded';
        setTimeout(() => {
          this.copiedId = null;
        }, 2000);
      } catch (err) {
        console.error('Failed to copy:', err);
      }
    },
  },
});
</script>

