<template>
  <div class="row items-center">
    <span class="q-mr-sm"
      >{{ $t(label || 'pagination_size') }}:</span
    >
    <q-select
      outlined
      dense
      v-model="pagination_size"
      :options="pagination_options"
      @update:model-value="update"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import {
  useDashboardStore,
  useTaskStore,
  useSettingStore,
} from 'src/store/main';
import { storeToRefs } from 'pinia';
import { tasks } from 'src/constants';

export default defineComponent({
  mixins: [],
  props: {
    modelType: {
      type: String,
      value: null,
    },
    label: {
      type: String,
      default: '',
    },
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == true && oldVal == false) {
          return;
        }
        this.getPaginationCount();
      },
    },
  },

  mounted() {
    this.getPaginationCount();
    this.validatePaginationSize();
  },

  methods: {
    getPaginationCount() {
      // For tasks, always use task-specific settings
      if (this.modelType === this.tasks) {
        const key = 'TASK_' + this.pagination_size_key;
        const valueFromSettings = this.user_settings[key];
        this.pagination_size = valueFromSettings;
        return;
      }

      // For dashboard: If a custom dashboard is selected with dashboard_page_count,
      // use that value instead of user settings to avoid overwriting dashboard pagination
      if (this.selected_dashboard?.id && this.selected_dashboard?.customizations?.dashboard_page_count) {
        this.pagination_size = this.selected_dashboard.customizations.dashboard_page_count;
        return;
      }

      // Otherwise, use user settings
      const valueFromSettings = this.user_settings[this.pagination_size_key];
      this.pagination_size = valueFromSettings;
    },
    async update() {
      if (this.modelType === this.tasks) {
        this.setTaskPaginationSize(String(this.pagination_size));
        const event = new CustomEvent('update_task_list', { detail: {} });
        document.dispatchEvent(event);
      } else {
        // If a custom dashboard is selected, mark it as updated (shows "Save dashboard changes" button)
        // Otherwise, save to user preferences
        if (this.isDashboardSelected()) {
          this.checkForDashboardUpdates();
        } else {
          await this.setPaginationSize();
        }
        this.triggerApplyFilters();
      }
    },
    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', {});
      document.dispatchEvent(event);
    },
    validatePaginationSize() {
      if (this.pagination_size <= 50) return;
      this.pagination_size = 50;
    },
  },
  data() {
    return {
      tasks,
    };
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const { pagination_size, pagination_size_key, selected_dashboard } =
      storeToRefs(dashboard_store);
    const { getPaginationSize, setPaginationSize, isDashboardSelected, checkForDashboardUpdates } = dashboard_store;

    const task_store = useTaskStore();
    const { setPaginationSize: setTaskPaginationSize } = task_store;

    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);

    return {
      setPaginationSize,
      getPaginationSize,
      pagination_size,
      pagination_size_key,
      pagination_options: ref(['10', '20', '25', '50']),
      setTaskPaginationSize,
      user_settings,
      loading_settings,
      isDashboardSelected,
      checkForDashboardUpdates,
      selected_dashboard,
    };
  },
});
</script>
<style lang="scss">
.user-select {
  width: 227px;
}
</style>
